const CAT_2={"id":2,"n":"Коледж / Ліцей","sub":"Системне навчання","e":"📐","col":"c2","blocks":[{"n":"📂 Робота з великими масивами інформації та конспектування","e":"","cards":[[102,"Метод Корнелла для конспектування лекцій","<div class=\"rule-note\">📝 <b>Метод Корнелла</b> — система конспектування, розроблена в Корнельському університеті. Розділяє запис на три зони: нотатки, ключові слова і підсумок. Завдяки структурі з трьох зон, полегшує повторення та засвоєння матеріалу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розмітка аркуша: три зони</b><br>Вертикальна лінія: 1/3 ліворуч (ключові слова), 2/3 праворуч (нотатки). Горизонтальна лінія внизу: 5–7 рядків (підсумок).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Під час лекції: правя колонка</b><br>Записуй основні думки, схеми, приклади. Не переписуй дослівно — фіксуй ідеї. Залишай пропуски для доповнень.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Після лекції: ліва колонка</b><br>Упродовж 24 годин запиши ключові слова і запитання до кожного блоку нотаток. «Яке запитання відповідає цьому блоку?»</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Підсумок внизу</b><br>Своїми словами: що ти зрозумів? Одне–два речення на весь аркуш. Це — сигнал для мозку «матеріал засвоєно».</div></div><div class=\"final-note\">📌 Використовуй ліву колонку для самоперевірки: закрий праву, дай відповіді на ключові слова. Те, де не відповів — повтори. Метод Корнелла + інтервальні повторення = ідеальна система.</div>"],[103,"Метод SQ3R для складної літератури","<div class=\"rule-note\">📖 <b>SQ3R</b> — активна стратегія читання для складних наукових текстів. Не читання, а діалог з текстом. Перетворює пасивний перегляд на глибоке розуміння.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>S — Survey (Огляд)</b><br>До читання: переглянь заголовки, підзаголовки, перший і останній абзаци, рисунки, висновки. Мета: отримати «карту» тексту (2–3 хв).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Q — Question (Запитання)</b><br>Перетвори кожен заголовок на запитання. «Теорія відносності» → «Що таке теорія відносності і що вона пояснює?» Запиши перед читанням.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>R1 — Read (Читання)</b><br>Читай з метою відповісти на свої запитання. Зупиняйся після кожного розділу.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>R2 + R3 — Recite + Review</b><br>Recite: закрий книгу — відповідь на запитання своїми словами. Review: наприкінці — переглянь усі запитання і підсумки.</div></div><div class=\"final-note\">💡 SQ3R сповільнює читання, але підвищує засвоєння в 2–3 рази. Для підручника або наукової статті — незамінний. Для художньої літератури — надлишковий.</div>"],[104,"Побудова ментальних карт (Mind Maps)","<div class=\"rule-note\">🗺️ <b>Ментальна карта</b> — візуальний інструмент для структурування знань. Відображає те, як мозок насправді організовує інформацію: не лінійно, а радіально. Автор методу — Тоні Б'юзен.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Центр: головна ідея</b><br>У центрі аркуша — одне слово або образ теми. Пиши горизонтально, використовуй A4 або A3 альбомно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гілки першого рівня</b><br>Від центру — 5–7 товстих гілок. Кожна = ключовий розділ теми. Одне слово на гілці, не фраза.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Гілки другого рівня і далі</b><br>Від кожної гілки — підгілки з деталями. Чим далі від центру — тим конкретніше. Додавай символи та малюнки.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Колір і образи — обов'язково</b><br>Кожна гілка — свій колір. Малюнки замість слів де можливо. Мозок запам'ятовує образи в 60 разів краще за слова.</div></div><div class=\"final-note\">📌 Використання: підготовка до іспиту, планування проєкту, конспект лекції, мозковий штурм. Інструменти: папір + фломастери, або Miro, MindMeister, XMind.</div>"],[105,"Експрес-синтез джерел","<div class=\"rule-note\">🔗 <b>Синтез джерел</b> — не переказ кожного окремо, а побудова власного погляду з кількох. Критична навичка для рефератів, есе та дослідницьких робіт.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: прочитай і позначте позицію кожного автора</b><br>Для кожного джерела: 1 речення — основна теза. Позначки: погоджується/не погоджується/доповнює.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: знайди збіги та розбіжності</b><br>Що всі автори визнають? Де розходяться? Розбіжності — найцінніше місце для власного аналізу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: побудуй власну позицію</b><br>На основі аналізу: твоя теза. Підкріпи цитатами з кількох джерел, а не лише одного.</div></div><div class=\"final-note\">💡 Слабкий текст: «Автор А сказав X. Автор Б сказав Y. Автор В сказав Z.» Сильний текст: «Більшість дослідників вважають X (А, Б), проте В доводить Y, що пояснює…» — це синтез.</div>"],[106,"Метод Zettelkasten","<div class=\"rule-note\">🗃️ <b>Zettelkasten</b> (нім. «ящик для карток») — система атомних нотаток із перехресними посиланнями. Розроблена соціологом Нікласом Луманом, який написав 70 книг і 400 статей завдяки їй.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Атомна нотатка</b><br>Одна ідея = одна картка. Не тема, не розділ — одна думка. Пиши своїми словами, не копіюй цитату.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Унікальний ідентифікатор</b><br>Кожна картка має ID: дата або номер. Дозволяє посилатися між картками: «Це пов'язано з ідеєю #2024-11-05».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перехресні посилання</b><br>Нова картка → шукай, з якими старими вона пов'язана → додай посилання в обидві. З часом виникає «граф ідей».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Постійна база — не архів</b><br>Zettelkasten — не сховище прочитаного, а жива система думок. Регулярно переглядай і з'єднуй нові ідеї зі старими.</div></div><div class=\"final-note\">📌 Цифрові інструменти: Obsidian (найпопулярніший), Roam Research, Logseq. Навіть паперовий варіант у зошиті з нумерацією — уже працює. Особливо ефективний для гуманітарних та дослідницьких напрямків.</div>"],[107,"Аналіз аргументації в лонгрідах","<div class=\"rule-note\">🔍 <b>Аналіз аргументації</b> — навичка критичного мислення. Дозволяє за 10 хвилин зрозуміти структуру великої статті, не читаючи кожне слово. Незамінна для наукових та аналітичних текстів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди головну тезу</b><br>Зазвичай у вступі або висновках. Запитай: «Що саме автор стверджує?» Запиши одним реченням.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди докази</b><br>Як автор підтверджує тезу? Факти, дослідження, статистика, приклади. Позначай їх на полях: «Д».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди контраргументи</b><br>Чи визнає автор протилежну точку зору? Якщо так — це ознака чесного аргументу. Якщо ні — шукай слабкі місця.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Оціни якість аргументу</b><br>Чи є докази конкретними? Чи джерела надійні? Чи логічний перехід від доказів до висновку? Запиши свою оцінку.</div></div><div class=\"final-note\">💡 Запитання-детектори слабкої аргументації: «Це факт чи думка?», «Звідки це відомо?», «А якщо навпаки?». Натреновані на цих запитаннях — ти читаєш будь-який текст критично.</div>"],[108,"Порівняльні матричні таблиці","<div class=\"rule-note\">📊 <b>Матрична таблиця</b> — потужний інструмент для зіставлення кількох об'єктів за однаковими критеріями. Перетворює хаос порівнянь на структуровану картину.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач об'єкти порівняння (рядки)</b><br>Що порівнюєш? Держави, теорії, методи, події, персонажі. Запиши їх у рядки таблиці.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Визнач критерії (стовпці)</b><br>За якими ознаками порівнюєш? Дата, причина, результат, особливості. Критерії мають бути однакові для всіх об'єктів.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Заповни клітинки — коротко</b><br>Одне–два слова або символ (+/–). Не переказуй — фіксуй суть. Порожня клітинка = «немає даних».</div></div><div class=\"final-note\">📌 Приклади використання: порівняння революцій (Французька/Американська), зіставлення наукових теорій, аналіз умов задачі. Готова таблиця — ідеальна основа для параграфу есе або відповіді на іспиті.</div>"],[109,"Алгоритм аналізу першоджерел","<div class=\"rule-note\">📜 <b>Аналіз першоджерела</b> — базова навичка дослідника. Документ, лист, закон, промова — не читай як художню літературу. Застосовуй систему «5 запитань».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Хто? — Автор і контекст</b><br>Хто написав? Яка його позиція, статус, інтереси? Чи може автор бути упередженим?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли і де? — Час і місце</b><br>Коли створено документ? Яка була ситуація тоді? Як це впливає на зміст?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Для кого? — Аудиторія</b><br>Кому адресований документ? Яка публічна/приватна мета? Аудиторія визначає тон і зміст.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Що і навіщо? — Зміст і мета</b><br>Яка головна думка? Яку реакцію хотів викликати автор? Що замовчується?</div></div><div class=\"final-note\">💡 Завершальне запитання: «Чому цей документ зберігся до нашого часу?» Те, що збереглось — не випадково. Це вже інтерпретація.</div>"],[110,"Конспектування медиа-матеріалів","<div class=\"rule-note\">🎬 <b>Відеолекція ≠ пасивний перегляд.</b> Конспектування відео — активна робота, яка суттєво підвищує засвоєння порівняно з пасивним переглядом без занотовування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>До перегляду: підготовка</b><br>Переглянь опис і заголовки розділів. Склади 3–5 запитань, на які очікуєш відповідь. Відкрий зошит.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Під час: таймкоди + ключові думки</b><br>Не стенограма — ключові ідеї. Записуй таймкод [12:34] для важливих місць. Пропусти не важливе.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пауза — твій найкращий інструмент</b><br>Складний момент → пауза → занотував → продовжуй. Перемотуй лише якщо не зрозумів, не «на всякий випадок».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Після: власний підсумок</b><br>Закрий зошит. Запиши 3–5 головних ідей відео своїми словами. Це — активне кодування в пам'ять.</div></div><div class=\"final-note\">📌 Для онлайн-курсів: YouTube дозволяє швидкість 1.25–1.5x — економить час без втрати розуміння. Субтитри + нотатки = подвійне кодування (аудіо + текст).</div>"],[111,"Техніка «Викрадач тез»","<div class=\"rule-note\">⚡ <b>«Викрадач тез»</b> — метод швидкого екстрактування суті статті за 5–7 хвилин. Не замінює повне читання, але дозволяє швидко оцінити цінність матеріалу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: вступ — 1 хвилина</b><br>Прочитай перший абзац. Автор зазвичай формулює проблему і свою позицію саме тут.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: перший речення кожного абзацу</b><br>Пробіжи очима по перших реченнях усіх абзаців. У добре структурованих текстах саме перші речення містять ключову думку абзацу — це стандарт академічного та публіцистичного письма.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: висновки — повністю</b><br>Останній розділ або абзаци — читай уважно. Тут автор підсумовує, що доведено і що з цього випливає.</div></div><div class=\"final-note\">💡 Після «Викрадача тез» запитай: «Чи варто читати повністю?» Якщо тема розкрита — ні. Якщо знайшов потрібний аргумент — читай лише той розділ. Це не лінощі — це ефективність.</div>"],[112,"Створення флеш-карток в Anki","<div class=\"rule-note\">🃏 <b>Anki</b> — програма для інтервальних повторень (Spaced Repetition). Алгоритм показує картку саме тоді, коли мозок ось-ось забуде. Найефективніший науково доведений метод довготривалого запам'ятовування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правило атомності</b><br>Одна картка = одна ідея. Не «Розкажи про фотосинтез» — а «Де в клітині відбувається фаза Кальвіна?». Конкретне питання — конкретна відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мінімум слів на картці</b><br>Запитання: максимум 1–2 рядки. Відповідь: 1–3 слова або речення. Довга картка = стрес при повторенні.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Категорії і теги</b><br>Одразу додавай теги: предмет, тема, тип (формула, дата, термін). Пізніше зможеш фільтрувати і повторювати лише потрібне.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Щоденний мінімум</b><br>15–20 хвилин щодня > 2 години раз на тиждень. Регулярність — ключ. Навіть 10 карток на день = 300 на місяць.</div></div><div class=\"final-note\">📌 Anki — безкоштовний на ПК і Android (платний на iOS). Є готові колоди: медицина, мови, право. Синхронізація через AnkiWeb. Альтернативи: Quizlet, RemNote.</div>"],[113,"Трансформація тексту в алгоритм","<div class=\"rule-note\">⚙️ <b>Алгоритмізація тексту</b> — перетворення описового тексту на послідовність конкретних кроків. Критична навичка для точних наук, програмування і процедурного мислення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди послідовність дій</b><br>Підкресли дієслова: «нагрій», «додай», «перевір», «якщо… то». Це кістяк алгоритму.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Виділи умови і розгалуження</b><br>Слова «якщо», «коли», «залежно від» → ромб рішення в блок-схемі. Два виходи: Так / Ні.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Склади блок-схему або нумерований список</b><br>Старт → кроки → рішення → кінець. Або: 1. Зроби А. 2. Якщо В — перейди до 4. 3. Зроби С...</div></div><div class=\"final-note\">📌 Застосування: хімічний синтез, математичний алгоритм, медична процедура, юридична норма, рецепт. Текст → алгоритм = перевірка розуміння: якщо не можеш алгоритмізувати — не розумієш.</div>"],[114,"Кодове маркування тексту","<div class=\"rule-note\">✏️ <b>Кодове маркування</b> — система позначок на берегах тексту для активного читання. Перетворює пасивний перегляд на діалог з автором.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Базовий набір символів</b><br>✓ — знайоме, погоджуюсь. + — нова і важлива ідея. ? — незрозуміло або сумнівно. ! — дивує, важливо запам'ятати. ✗ — не погоджуюсь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підкреслення з кольором</b><br>Жовтий — ключові терміни. Синій — визначення. Зелений — приклади. Рожевий — висновки. Не підкреслюй більше 10–15% тексту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Берегові нотатки</b><br>Коротке слово або запитання на берегах: «чому?», «=формула», «іспит», «суперечить §3». Пізніше — готовий конспект для повторення.</div></div><div class=\"final-note\">💡 Правило: маркуй лише те, що справді важливо. Якщо підкреслено все — не підкреслено нічого. Маркування в е-книгах: виділення + нотатка = той самий ефект.</div>"],[115,"Хронологічні таблиці-матриці","<div class=\"rule-note\">📅 <b>Хронологічна матриця</b> — таблиця, що поєднує часову вісь з аналітичними критеріями. Ідеальна для вивчення історичних процесів, наукових революцій, розвитку ідей.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура: час + критерії</b><br>Рядки: події або часові відрізки. Стовпці: причини, учасники, перебіг, наслідки, значення. Однакові критерії для всіх подій.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Паралельні хронології</b><br>Декілька процесів в одній таблиці — видно зв'язки: «Поки в Європі відбувалося X, в Азії — Y». Синхронія — ключ до розуміння.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Використання на іспиті</b><br>Таблиця з пам'яті відтворюється легше за зв'язний текст. Під час відповіді — відтвори таблицю подумки, потім розкажи.</div></div><div class=\"final-note\">📌 Лайфхак: зроби зведену хронологічну таблицю по всьому курсу на початку семестру — порожню. Заповнюй по мірі вивчення тем. Наприкінці семестру — готова шпаргалка і розуміння структури.</div>"],[116,"Візуалізація статистики","<div class=\"rule-note\">📈 <b>Статистика без візуалізації</b> — цифри, що нічого не говорять. Правильний графік робить тренд очевидним за 3 секунди.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вибір типу графіка</b><br>Динаміка в часі → лінійний. Порівняння категорій → стовпчиковий. Частки цілого → секторний (до 5 секторів). Розподіл → гістограма. Зв'язок між змінними → точковий.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Обов'язкові елементи</b><br>Заголовок (що показано). Підписи осей + одиниці виміру. Джерело даних. Легенда (якщо кілька рядів).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Уникай графічної брехні</b><br>Вісь Y від нуля (або позначай розрив). Однакові масштаби при порівнянні. Розмір кола/фігури пропорційний значенню, а не радіусу.</div></div><div class=\"final-note\">💡 Інструменти: Excel/Google Sheets для базових. Canva для презентацій. Datawrapper (безкоштовний) для публікацій. Python/matplotlib для складного аналізу.</div>"],[117,"Причинно-наслідкове картографування","<div class=\"rule-note\">🔄 <b>Причинно-наслідкова карта</b> — візуалізація зв'язків між чинниками та їх наслідками. Допомагає побачити не лише «що сталося», а «чому» і «що з цього випливає».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди центральну подію або проблему</b><br>Запиши в центрі аркуша. Це «вузол» карти.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гілки «Чому?» — причини</b><br>Ліворуч або вгору: стрілки від причин до центру. Первинні причини → вторинні → третинні. Запитуй «Чому?» 5 разів.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Гілки «Що з цього?» — наслідки</b><br>Праворуч або вниз: стрілки від центру до наслідків. Прямі → опосередковані → довгострокові.</div></div><div class=\"final-note\">📌 Метод «5 Чому» (Toyota): для кожної причини запитуй «Чому це сталося?» до 5 разів — знаходиш корінь проблеми. Приклад: катастрофа → недогляд → втома → понаднормова робота → нестача персоналу → бюджет.</div>"],[118,"Складання предметного глосарію","<div class=\"rule-note\">📒 <b>Власний глосарій</b> — не переписування словника, а авторське пояснення термінів. «Пояснив іншому — зрозумів сам».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формат запису</b><br>Термін. Офіційне визначення (1 рядок). Власними словами (1–2 речення). Приклад або аналогія. Суміжні терміни / антоніми.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли поповнювати</b><br>Одразу при зустрічі нового терміну — не «потім». 3 хвилини одразу краще, ніж 30 хвилин перед іспитом.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Система пошуку</b><br>Алфавітний порядок або за темами. У цифровому варіанті — хештеги і пошук. У паперовому — закладки-розділювачі.</div></div><div class=\"final-note\">💡 Тест глосарію: закрий пояснення — чи можеш відтворити своїми словами? Якщо ні — переформулюй. Глосарій, який ти не можеш переказати — не твій.</div>"],[119,"Пошук логічних помилок у тексті","<div class=\"rule-note\">🧩 <b>Логічні помилки</b> (хиби) — поширені в публіцистиці, рекламі, дискусіях. Вміти їх розпізнавати = критичне мислення в дії.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Узагальнення без підстав</b><br>«Усі студенти ледачі» — один приклад ≠ правило. Запитай: «Усі? Завжди? Наскільки репрезентативна вибірка?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Хибна аналогія</b><br>«Держава як сім'я» — схожість не означає тотожність. Де аналогія ламається?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Аргумент до авторитету</b><br>«Знаменитий спортсмен рекомендує ці вітаміни» — статус не замінює докази.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Підміна поняття (соломяна людина)</b><br>Автор спрощує або спотворює позицію опонента, щоб легше спростувати. Запитай: «Чи це справді те, що стверджує опонент?»</div></div><div class=\"final-note\">📌 Повний список хиб: False Dichotomy, Slippery Slope, Ad Hominem, Appeal to Emotion. Знання 10 найпоширеніших хиб — зброя при читанні ЗМІ і участі в дискусіях.</div>"],[120,"Idea Mapping для семінарів","<div class=\"rule-note\">💡 <b>Idea Mapping</b> — ментальна карта, зосереджена не на структурі теми, а на ідеях для обговорення. Готує до живого семінарського діалогу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Центр: питання семінару</b><br>Не тема, а конкретне питання: «Чи можна виправдати революцію?» Питання → думки, а не факти.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гілки: твої позиції і аргументи</b><br>Запиши 3–5 власних думок. До кожної — 1–2 аргументи або приклади. Це твоя «заготовка» для виступу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Гілки: контраргументи</b><br>Що скажуть ті, хто не погоджується? Запиши — і підготуй відповідь. Той, хто передбачає контраргументи, виграє дискусію.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запитання до аудиторії</b><br>Підготуй 1–2 запитання, які можеш поставити іншим. Активний учасник — не лише той, хто говорить, а й той, хто питає.</div></div><div class=\"final-note\">📌 Час підготовки: 15–20 хвилин. Результат: впевнений виступ, 2–3 змістовних репліки, 1 цікаве запитання. Оцінка на семінарі — не лотерея, а підготовка.</div>"],[121,"Організація цифрового архіву","<div class=\"rule-note\">🗂️ <b>Цифровий архів</b> — система зберігання навчальних матеріалів, де ти знаходиш потрібне за 30 секунд. Без системи — хаос, що з'їдає час.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура папок</b><br>Рівень 1: Навчальний рік. Рівень 2: Предмет. Рівень 3: Тип (Лекції / ДЗ / Проєкти / Матеріали). НЕ: «Нові папки» і «Різне».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Іменування файлів</b><br>2024-11-15_Фізика_Лекція_Динаміка.pdf — дата + предмет + тип + тема. Пошук за будь-якою частиною.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило двох версій</b><br>Локальна копія + хмара (Google Drive, OneDrive). Одна копія = ризик втрати. Дві = спокій.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Регулярне прибирання</b><br>Раз на семестр: видали дублікати, заархівуй старе, переглянь структуру. 1 година = пів року порядку.</div></div><div class=\"final-note\">💡 Теги замість папок (Notion, Obsidian): один файл може належати кільком категоріям одночасно. Потужніше за ієрархічні папки для складних матеріалів.</div>"]]},{"n":"🔬 Точні науки, аналітика та складні задачі","e":"","cards":[[122,"Метод зворотного аналізу","<div class=\"rule-note\">🔁 <b>Зворотний аналіз</b> (від відповіді до умови) — стратегія розв'язання складних задач, де прямий шлях незрозумілий. Особливо ефективний у математиці, логіці та програмуванні.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши, що потрібно отримати</b><br>Чітко: яке значення, яка умова, який вигляд відповіді. «Довести, що A = B» → починаємо з B.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запитай: «Що має бути безпосередньо перед цим?»</b><br>Рухайся назад крок за кроком. Яка умова або перетворення дає потрібний результат?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Будуй ланцюжок до вихідних даних</b><br>Продовжуй рухатись у зворотному напрямку, поки не прийдеш до даних умови.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запиши розв'язання вперед</b><br>Коли ланцюжок побудований — переформулюй від умови до відповіді. Це і є розв'язання.</div></div><div class=\"final-note\">📌 Класичний приклад: геометричні доведення. Допоміжний елемент неочевидний прямо, але зворотний аналіз показує: «якщо провести бісектрису, отримаємо рівні трикутники».</div>"],[123,"Електронний баланс у хімії","<div class=\"rule-note\">⚗️ <b>Метод електронного балансу</b> — алгоритм розстановки коефіцієнтів у окисно-відновних реакціях (ОВР). Базується на законі збереження заряду.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: визнач ступені окислення</b><br>Для кожного елемента в реакції визнач ступінь окислення до і після. Пам'ятай правила: O = -2, H = +1, сума = 0 або заряду іона.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: знайди зміну ступенів</b><br>Елемент, що підвищив ступінь = окислюється (відновник). Знизив — відновлюється (окислювач). Запиши зміни.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: зрівняй баланс електронів</b><br>Кількість відданих електронів = кількість прийнятих. Знайди НСК, постав коефіцієнти перед відповідними речовинами.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Крок 4: зрівняй іони, H, O, H₂O</b><br>Перевір: закон збереження маси виконується? Якщо ні — зрівняй кислотний/лужний залишок.</div></div><div class=\"final-note\">📌 Алгоритм: ступені → зміни → баланс електронів → коефіцієнти → перевірка. Метод напівреакцій (іонно-електронний) — альтернатива для розчинів.</div>"],[124,"Векторний аналіз у фізиці","<div class=\"rule-note\">📐 <b>Векторний аналіз</b> — розкладання сил та швидкостей на проекції для розв'язання задач із механіки. Без цього навику більшість задач 10–11 класу нерозв'язні.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Намалюй систему координат</b><br>Вибери орієнтацію осей зручно: зазвичай OX — вздовж руху, OY — перпендикулярно. Позначай з виноскою.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Нанеси всі сили на малюнок</b><br>Кожна сила — стрілка від тіла в потрібному напрямку. Підпиши: mg, N, F, Fтр. Не забудь вагу!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розклади кожну силу на проекції</b><br>Якщо сила під кутом α: Fx = F·cos(α), Fy = F·sin(α). Знак залежить від напрямку: проти осі = мінус.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Складай рівняння Ньютона для кожної осі</b><br>∑Fx = m·ax, ∑Fy = m·ay. Два рівняння → два невідомих. Вирішуй систему.</div></div><div class=\"final-note\">📌 Типові помилки: забути нормальну реакцію N, не врахувати знак проекції, переплутати sin і cos. Завжди перевіряй: чи всі сили нанесено на малюнок?</div>"],[125,"Виведення хімічних формул","<div class=\"rule-note\">🧪 <b>Вивід хімічної формули</b> за масовими частками — стандартна задача хімії. Алгоритм однаковий для будь-якої речовини.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши масові частки у відсотках</b><br>C: 40%, H: 6.67%, O: 53.33% — переведи в грами (якщо ∑ = 100%, то в 100 г речовини є стільки грамів кожного елемента).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поділи на атомну масу</b><br>C: 40/12 = 3.33 моль. H: 6.67/1 = 6.67 моль. O: 53.33/16 = 3.33 моль. Отримуємо кількості атомів.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поділи на найменше</b><br>Найменше = 3.33. C: 3.33/3.33 = 1. H: 6.67/3.33 = 2. O: 3.33/3.33 = 1. Емпірична формула: CH₂O.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Знайди молярну масу та справжню формулу</b><br>Якщо відомо M, то: n = M / M(CH₂O) = M/30. Справжня формула: (CH₂O)n.</div></div><div class=\"final-note\">📌 Числа не завжди цілі? Якщо отримав 1 : 1.5 : 2 — помнож усі на 2 → 2 : 3 : 4. Правило: множи, щоб отримати цілі числа (на 2, 3, 4).</div>"],[126,"Дослідження функцій у математиці","<div class=\"rule-note\">📉 <b>Повне дослідження функції</b> — стандартний алгоритм аналізу, що дає повну картину поведінки функції. Обов'язкове вміння для ЗНО/НМТ і вишу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>1. Область визначення D(f)</b><br>При яких x функція існує? Знаменник ≠ 0, підкореневий вираз ≥ 0, логарифм &gt; 0.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>2. Парність/непарність, монотонність</b><br>f(-x) = f(x) → парна. f(-x) = -f(x) → непарна. Похідна f' &gt; 0 → зростає, f' &lt; 0 → спадає.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>3. Екстремуми: f'(x) = 0</b><br>Знайди критичні точки. Перевір знак f' зліва і справа від точки: зміна + → - = максимум, - → + = мінімум.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>4. Асимптоти і будова графіка</b><br>Вертикальні: x → точки розриву. Горизонтальні: lim f(x) при x→±∞. Намалюй графік з усіма знайденими точками.</div></div><div class=\"final-note\">📌 Порядок: D(f) → нулі → знак → парність → f' → екстремуми → асимптоти → графік. Пропустив крок — графік буде неправильним.</div>"],[127,"Графічне моделювання у фізиці","<div class=\"rule-note\">📐 <b>Фізичне креслення</b> — обов'язковий перший крок у розв'язанні задачі. «Намалював — зрозумів». Малюнок дозволяє побачити систему цілком і уникнути типових помилок з напрямком сил та знаками.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Намалюй систему схематично</b><br>Тіла — прямокутники або кола. Поверхні — лінії. Позначай літерами: m₁, m₂, θ, L. Не треба художньо — треба точно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Нанеси всі сили</b><br>Кожна сила — стрілка від тіла в напрямку дії. Підпишіть: mg (вага), N (нормальна реакція), T (натяг), f (тертя).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Позначте вісі координат</b><br>OX та OY прямо на малюнку. Вибирай зручно: OX — вздовж руху або похилої площини.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Для кінематики: графіки v(t) і x(t)</b><br>Рівноприскорений рух: v(t) — пряма, x(t) — парабола. Нахил v(t) = прискорення. Площа під v(t) = переміщення.</div></div><div class=\"final-note\">📌 Правило: без малюнка — не починати розв'язання. Перевірив малюнок — перевірив розуміння умови.</div>"],[128,"Дерева рішень у комбінаториці","<div class=\"rule-note\">🌳 <b>Дерево рішень</b> — наочний перебір усіх можливих варіантів. Незамінне для задач на перестановки, комбінації та ймовірності.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: визнач перший вибір</b><br>Корінь дерева — початковий стан. Гілки від кореня — всі варіанти першого кроку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: від кожної гілки — наступні вибори</b><br>Для кожного варіанту першого кроку намалюй варіанти другого. І так далі до кінця.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: підрахуй кінцеві вузли</b><br>Кількість «листків» дерева = кількість усіх можливих результатів. Це і є відповідь на «скільки варіантів».</div></div><div class=\"final-note\">💡 Правило множення: якщо перший крок має m варіантів, другий — n, то разом m×n. Дерево рішень — наочне підтвердження цього правила. Для великих n — формули (Pₙ, Cₙᵏ, Aₙᵏ).</div>"],[129,"Аналіз розмірностей","<div class=\"rule-note\">📏 <b>Аналіз розмірностей</b> — перевірка фізичної формули через одиниці вимірювання. Якщо розмірності не збігаються — формула хибна.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши розмірності кожної величини</b><br>[v] = м/с, [a] = м/с², [F] = кг·м/с², [E] = Дж = кг·м²/с². Знай основні одиниці СІ напам'ять.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підстав розмірності у формулу</b><br>Замість літер — їх розмірності. Наприклад: F = ma → [кг·м/с²] = [кг]·[м/с²] ✓</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевір рівність лівої і правої частини</b><br>Якщо розмірності рівні — формула може бути правильною. Якщо ні — точно хибна.</div></div><div class=\"final-note\">📌 Аналіз розмірностей не доводить правильність формули (числові коефіцієнти він не перевіряє), але гарантовано виявляє помилку. Корисно при самоперевірці на іспиті.</div>"],[130,"Операції з матрицями та векторами","<div class=\"rule-note\">🔢 <b>Матриці та вектори</b> — мова лінійної алгебри. Базові операції потрібні для фізики, програмування, економіки та машинного навчання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Додавання матриць</b><br>Лише однакових розмірів. Складаємо елементи на відповідних позиціях: (A+B)ᵢⱼ = aᵢⱼ + bᵢⱼ.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Множення матриць</b><br>A(m×n) · B(n×p) = C(m×p). Елемент cᵢⱼ = сума добутків i-го рядка A на j-й стовпець B. Порядок важливий: AB ≠ BA.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Визначник 2×2</b><br>det(A) = a₁₁·a₂₂ − a₁₂·a₂₁. Визначник = 0 → система не має єдиного розв'язку.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Скалярний добуток векторів</b><br>a·b = |a|·|b|·cos(θ) = a₁b₁ + a₂b₂ + a₃b₃. Результат — число. Якщо = 0 → вектори перпендикулярні.</div></div><div class=\"final-note\">📌 Вектори у фізиці: швидкість, сила, прискорення — мають напрямок. Скаляри: маса, час, температура — лише число. Векторне множення дає вектор, перпендикулярний обом.</div>"],[131,"Зведення тригонометричних рівнянь","<div class=\"rule-note\">📐 <b>Тригонометричні рівняння</b> — зводяться до базових форм: sin x = a, cos x = a, tg x = a. Алгоритм однаковий для всіх.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: спрости до базової форми</b><br>Використовуй тотожності: sin²x + cos²x = 1, подвійний кут, сума → добуток. Мета: отримати одну тригонометричну функцію.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: запиши загальний розв'язок</b><br>sin x = a: x = (-1)ⁿ arcsin(a) + πn. cos x = a: x = ± arccos(a) + 2πn. tg x = a: x = arctg(a) + πn.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: перевір ОДЗ</b><br>Для tg: cos x ≠ 0. Для ctg: sin x ≠ 0. Виключи зайві корені.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Крок 4: виділи корені з заданого інтервалу</b><br>Якщо задано [0; 2π] — підстав n = 0, 1, 2… і знайди всі x, що потрапляють в інтервал.</div></div><div class=\"final-note\">💡 Таблиця значень напам'ять: sin(π/6)=½, sin(π/4)=√2/2, sin(π/3)=√3/2, sin(π/2)=1. Знаючи першу чверть — відновлюєш усі.</div>"],[132,"Математичне моделювання в економіці","<div class=\"rule-note\">💰 <b>Математичні моделі в економіці</b> — переведення реальної ситуації на мову функцій, рівнянь і нерівностей.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач змінні</b><br>Що є невідомим? x — кількість товару, t — час, r — відсоткова ставка. Запиши, що означає кожна змінна.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Склади рівняння або функцію</b><br>Прибуток = Дохід − Витрати. P(x) = R(x) − C(x). Лінійна, квадратична або показникова — залежно від умови.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди оптимум</b><br>Максимум прибутку або мінімум витрат: похідна P'(x) = 0. Перевір знак P″ для підтвердження максимуму/мінімуму.</div></div><div class=\"final-note\">📌 Класичні моделі: попит-пропозиція (лінійні рівняння), складний відсоток (показникова функція Aₙ = A₀·(1+r)ⁿ), беззбитковість (точка, де P(x)=0).</div>"],[133,"Статистична обробка вимірювань","<div class=\"rule-note\">📊 <b>Статистична обробка</b> — відповідь на питання: «Наскільки точний мій результат?» Обов'язкова частина лабораторних і дослідницьких робіт.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Середнє значення &lt;x̄&gt;</b><br>x̄ = (x₁ + x₂ + ... + xₙ) / n. Найкраща оцінка істинного значення при n вимірюваннях.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Абсолютна похибка Δx</b><br>Δxᵢ = |xᵢ − x̄|. Середня абсолютна похибка: Δx = Σ|Δxᵢ| / n. Результат: x = x̄ ± Δx.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відносна похибка ε</b><br>ε = (Δx / x̄) · 100%. Показує точність у відсотках. Прийнятно: ε &lt; 5% для шкільних дослідів.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевірка на викиди</b><br>Якщо одне значення різко відхиляється (&gt; 3Δx) — може бути похибкою вимірювання. Перевір і виключи обґрунтовано.</div></div><div class=\"final-note\">💡 Запис результату: x = (5.42 ± 0.03) см, ε = 0.6%. Ніколи не пиши «x ≈ 5.42» без вказівки похибки — це не науковий запис.</div>"],[134,"Кроковий диференціал та інтеграл","<div class=\"rule-note\">∫ <b>Похідна і первісна</b> — два фундаментальних інструменти математичного аналізу. Похідна — швидкість зміни. Інтеграл — накопичення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Алгоритм диференціювання</b><br>1. Степенева: (xⁿ)' = n·xⁿ⁻¹. 2. Складна функція: (f(g(x)))' = f'(g)·g'. 3. Добуток: (uv)' = u'v + uv'. 4. Частка: (u/v)' = (u'v − uv')/v².</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Таблиця основних похідних</b><br>(sin x)' = cos x. (cos x)' = −sin x. (eˣ)' = eˣ. (ln x)' = 1/x. (aˣ)' = aˣ·ln a.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Алгоритм інтегрування</b><br>∫xⁿdx = xⁿ⁺¹/(n+1) + C. ∫sin x dx = −cos x + C. ∫eˣdx = eˣ + C. Метод заміни: ∫f(g(x))g'(x)dx = ∫f(u)du.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Визначений інтеграл = площа</b><br>∫ₐᵇ f(x)dx = F(b) − F(a), де F — первісна. Геометричний зміст: площа під кривою від a до b.</div></div><div class=\"final-note\">📌 Зв'язок: якщо F'(x) = f(x), то ∫f(x)dx = F(x) + C. Похідна і інтеграл — обернені операції (теорема Ньютона–Лейбніца).</div>"],[135,"Задачі на рух під кутом до горизонту","<div class=\"rule-note\">🎯 <b>Кидання під кутом</b> — суперпозиція рівномірного горизонтального і рівноприскореного вертикального руху. Незалежність рухів — ключовий принцип.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розклади початкову швидкість</b><br>v₀ₓ = v₀·cos α (горизонтальна). v₀ᵧ = v₀·sin α (вертикальна). α — кут до горизонту.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Рівняння руху для кожної осі</b><br>OX: x = v₀ₓ·t (рівномірно). OY: y = v₀ᵧ·t − g·t²/2 (рівноприскорено). Осі незалежні!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди час польоту</b><br>При y = 0 (повернення на землю): 0 = v₀ᵧ·t − g·t²/2 → t = 2v₀ᵧ/g = 2v₀·sin α / g.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Знайди дальність і висоту</b><br>Дальність: L = v₀ₓ·t. Максимальна висота: H = v₀ᵧ²/(2g). Максимальна дальність при α = 45°.</div></div><div class=\"final-note\">📌 Корисні наслідки: кути α і (90°−α) дають однакову дальність. Максимальна дальність L = v₀²/g (при α = 45°). Час до вершини = половина часу польоту.</div>"],[136,"Метод відсікання в тестах","<div class=\"rule-note\">✂️ <b>Метод відсікання</b> — стратегія роботи з тестами множинного вибору. Дозволяє правильно відповісти навіть при неповному знанні теми.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: виключи очевидно хибні</b><br>Зазвичай 1–2 варіанти явно неправильні. Виключи їх одразу. Залишилось 2–3 варіанти.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: шукай «занадто категоричні» відповіді</b><br>Варіанти з «завжди», «ніколи», «лише», «всі» — частіше хибні. Наука рідко абсолютна.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: порівняй схожі варіанти</b><br>Якщо два варіанти майже однакові — відповідь одна з них. Знайди відмінність і вибери правильну.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Крок 4: «найповніший» варіант</b><br>Якщо два варіанти правильні, але один включає інший — правильний той, що ширший.</div></div><div class=\"final-note\">💡 Статистика: після виключення двох невірних варіантів вгадати з 50% ймовірністю краще, ніж залишати порожнім. Якщо немає штрафу за неправильну відповідь — відповідай завжди.</div>"],[137,"Розрахунок електричних кіл","<div class=\"rule-note\">⚡ <b>Закон Ома і правила Кірхгофа</b> — два інструменти для розрахунку будь-якого електричного кола.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Закон Ома для ділянки кола</b><br>I = U/R. Для повного кола: I = ε/(R + r), де ε — ЕРС, r — внутрішній опір. Потужність: P = I²R = U²/R = UI.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Послідовне і паралельне з'єднання</b><br>Послідовно: R = R₁+R₂, I однакові, U = U₁+U₂. Паралельно: 1/R = 1/R₁+1/R₂, U однакові, I = I₁+I₂.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перше правило Кірхгофа (вузлове)</b><br>Сума струмів у вузлі = 0. Струми, що входять — знак «+», виходять — «−».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Друге правило Кірхгофа (контурне)</b><br>Сума ЕРС у контурі = сума спадів напруги: ΣE = ΣIR. Обирай напрямок обходу — знаки відповідно.</div></div><div class=\"final-note\">📌 Алгоритм: намалюй схему → позначь невідомі струми → запиши рівняння Кірхгофа → вирішуй систему. Перевірка: сума потужностей джерел = сума потужностей споживачів.</div>"],[138,"Генетичні задачі на зчеплення","<div class=\"rule-note\">🧬 <b>Зчеплення генів</b> — гени, розташовані в одній хромосомі, успадковуються разом. Порушення зчеплення відбувається при кросинговері.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач тип зчеплення</b><br>Якщо гени в одній хромосомі: цис-конфігурація (AB/ab) або транс (Ab/aB). Позначають парами через дріб.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Нащадки без кросинговеру</b><br>Переважають батьківські класи: AB та ab (цис) або Ab та aB (транс). Частота ≈ 50% кожен.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нащадки з кросинговером</b><br>Рекомбінантні класи: менша частота. Частота кросинговеру = % рекомбінантів = відстань між генами (морганіди).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Зчеплення зі статтю</b><br>Гени в X-хромосомі: у самок — два алелі (XX), у самців — один (XY). Гемізиготність самців — прояв рецесивних ознак.</div></div><div class=\"final-note\">📌 Закон Моргана: гени в одній хромосомі утворюють групу зчеплення і успадковуються разом. Частота кросинговеру між генами = відстань у сантиморганах (сМ).</div>"],[139,"Логарифмічні перетворення","<div class=\"rule-note\">📊 <b>Логарифми</b> — зворотні до показникового: log_a(aˣ) = x. Незамінні в хімії (pH), фізиці (децибели), біології (ріст популяцій) і фінансах.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Основні властивості</b><br>log(ab) = log a + log b. log(a/b) = log a − log b. log(aⁿ) = n·log a. log_a(a) = 1. log_a(1) = 0.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формула переходу</b><br>log_a(b) = log_c(b) / log_c(a). На практиці: log₂(8) = ln(8)/ln(2) = 3. Переводь до зручної основи.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Логарифмічні рівняння</b><br>log_a(f(x)) = b → f(x) = aᵇ. ОДЗ: f(x) &gt; 0. Рівняння через заміну: нехай t = log_a(x) → зводиться до квадратного.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Логарифмічні нерівності</b><br>При a &gt; 1: log_a(f) &gt; log_a(g) ⟺ f &gt; g. При 0 &lt; a &lt; 1: нерівність змінюється на протилежну!</div></div><div class=\"final-note\">📌 pH = −log[H⁺]. Децибели: L = 10·log(I/I₀). Шкала Ріхтера — логарифмічна. Знання логарифмів = розуміння природних процесів.</div>"],[140,"Задачі на тепловий баланс","<div class=\"rule-note\">🌡️ <b>Тепловий баланс</b> — закон збереження енергії для теплових процесів: скільки тепла віддано = скільки прийнято.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Рівняння теплового балансу</b><br>Q_відд = Q_прийн. Або: ΣQ = 0, де тіла, що охолоджуються дають «−», що нагріваються — «+».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Нагрівання/охолодження без фазового переходу</b><br>Q = m·c·(T₂ − T₁). c — питома теплоємність. Якщо T₂ > T₁ → Q > 0 (тіло нагрівається).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Фазові переходи</b><br>Плавлення/кристалізація: Q = m·λ. Пароутворення/конденсація: Q = m·L. Температура не змінюється під час переходу!</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Алгоритм розв'язання</b><br>1. Визнач, які тіла нагріваються, які охолоджуються. 2. Запиши Q для кожного. 3. Склади баланс. 4. Вирішуй рівняння.</div></div><div class=\"final-note\">📌 Типова пастка: не врахувати фазовий перехід при досягненні температури плавлення. Якщо крига + гаряча вода: спочатку перевір, чи вистачає тепла на плавлення льоду.</div>"],[141,"Оформлення олімпіадних задач","<div class=\"rule-note\">🏆 <b>Оформлення на олімпіаді</b> — частина оцінки. Правильна відповідь без обґрунтування може дати 0 балів. Суворий запис — повні бали.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Дано / Знайти / Розв'язання / Відповідь</b><br>Класична структура фізичної задачі. На олімпіаді з математики: Умова → Доведення/Розв'язання → Відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Кожен крок — окремий рядок з поясненням</b><br>НЕ «= 42». → «Оскільки трикутники подібні (ознака кут-кут), то AB/CD = AC/CE, звідси AB = 42».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Посилання на теореми і формули</b><br>Явно вказуй: «за теоремою Піфагора», «за законом косинусів», «за властивістю арифметичної прогресії».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевірка і відповідь</b><br>Перевір одиниці виміру, знак результату, граничні випадки. Відповідь підкресли або виділи. Чи відповідає вона умові задачі?</div></div><div class=\"final-note\">💡 Секрет олімпіадника: часткове розв'язання з правильним обґрунтуванням дає більше балів, ніж правильна відповідь без пояснень. Пиши навіть те, що здається очевидним.</div>"]]},{"n":"✍️ Академічне письмо, реферати та проєкти","e":"","cards":[[142,"Анатомія вступу дослідницької роботи","<div class=\"rule-note\">📄 <b>Вступ дослідницької роботи</b> — не «передмова», а науковий контракт з читачем. Правильний вступ займає 1–2 сторінки і відповідає на 5 запитань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Актуальність</b><br>Чому ця тема важлива ЗАРАЗ? Яка проблема існує? Посилання на реальну ситуацію або прогалину в знаннях.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мета і завдання</b><br>Мета — одна: «Дослідити / розробити / визначити…». Завдання — 3–5 конкретних кроків для досягнення мети.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Об'єкт і предмет</b><br>Об'єкт — широке поле: «навчальна мотивація». Предмет — конкретний аспект: «вплив геймифікації на мотивацію учнів 7–9 класів».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Методи дослідження</b><br>Теоретичні (аналіз, синтез, порівняння) і практичні (спостереження, експеримент, анкетування, статистика).</div></div><div class=\"final-note\">📌 Типова помилка: «Я вирішив дослідити цю тему, тому що вона мене цікавить» — не актуальність. Актуальність = проблема в суспільстві, науці або практиці, яку вирішує робота.</div>"],[143,"Метод аргументації ПОПС","<div class=\"rule-note\">💬 <b>ПОПС-формула</b> — структура аргументу, яка гарантує переконливість. Позиція + Обґрунтування + Приклад + Судження.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>П — Позиція</b><br>Чітко сформулюй свою думку одним реченням: «Я вважаю, що…» або «На мою думку, …»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>О — Обґрунтування</b><br>Чому ти так вважаєш? Логічне пояснення: «Тому що…», «Це зумовлено тим, що…». Факт або логіка, а не емоція.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>П — Приклад</b><br>Конкретний приклад, який підтверджує: «Наприклад,…», «Це підтверджується…», «Зокрема,…». Статистика, факт, випадок.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>С — Судження</b><br>Підсумок: «Таким чином,…», «Отже, можна стверджувати, що…». Повертає до вихідної позиції, але вже підкріпленої.</div></div><div class=\"final-note\">📌 ПОПС застосовується: в есе, на семінарах, при захисті проєкту, у дискусії. 4 кроки = 4 абзаци або 4 репліки. Збалансований аргумент, що важко спростувати.</div>"],[144,"Формулювання дослідницької гіпотези","<div class=\"rule-note\">🔬 <b>Гіпотеза</b> — не здогадка, а перевірюване припущення. Відповідає на запитання: «Що буде, якщо…?» або «Чи пов'язані X і Y?»</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура гіпотези</b><br>«Якщо [умова/дія], то [очікуваний результат], тому що [теоретичне обґрунтування].» Три частини обов'язкові.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Критерій перевірності</b><br>Гіпотезу можна підтвердити або спростувати експериментом. «Учні краще навчаються» — не гіпотеза. «Учні групи А отримали на 15% вищі оцінки» — гіпотеза.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нульова і альтернативна гіпотези</b><br>H₀: «Немає різниці між групами». H₁: «Є різниця». Статистичне дослідження перевіряє, чи можна відхилити H₀.</div></div><div class=\"final-note\">💡 Погана гіпотеза: «Я думаю, що здоровий спосіб життя важливий». Добра: «Учні, які сплять 8+ годин, матимуть на 20% вищу академічну успішність, ніж ті, що сплять менше 6 годин».</div>"],[145,"Оформлення бібліографії","<div class=\"rule-note\">📚 <b>Бібліографія</b> — не формальність, а доказ наукової чесності. Правильне оформлення захищає від звинувачень у плагіаті.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Стандарт ДСТУ (для шкіл і вишів України)</b><br>Прізвище І.П. Назва книги. — Місто: Видавництво, Рік. — Кількість с. Приклад: Іваненко О.П. Основи хімії. — Київ: Освіта, 2020. — 256 с.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Стандарт APA (міжнародний)</b><br>Іваненко, О.П. (2020). Основи хімії. Освіта. Для статті: Прізвище, Ім'я. (Рік). Назва статті. Назва журналу, Том(Номер), Сторінки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Веб-джерела</b><br>Автор. (Рік). Назва сторінки. Назва сайту. URL. Дата звернення: ДД.ММ.РРРР.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Нумерація і порядок</b><br>За алфавітом (APA) або в порядку цитування (ДСТУ). Нумерація: [1], [2]… Посилання в тексті: [1, с. 45] або (Іваненко, 2020, с. 45).</div></div><div class=\"final-note\">📌 Правило: кожне твердження не є загальновідомим фактом → посилання обов'язкове. «Вода кипить при 100°C» — посилання не потрібне. «Успішність зросла на 23%» — джерело обов'язкове.</div>"],[146,"Метод «Скелет есе»","<div class=\"rule-note\">🦴 <b>Скелет есе</b> — детальний план перед написанням. 20 хвилин планування економлять 2 години переписування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Теза у вступі</b><br>Одне речення: твоя головна думка. Увесь текст есе — розгортання і доведення цієї тези.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Три абзаци основної частини</b><br>Кожен абзац: мінітеза (1 реч.) → доказ → приклад → зв'язок з головною тезою. Запиши «кістяк» кожного абзацу до написання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Контраргумент і відповідь на нього</b><br>Визнай протилежну точку зору в одному абзаці, потім спростуй або обмеж її. Це додає тексту глибини.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Висновок = перефразована теза + наслідок</b><br>НЕ повторюй вступ слово в слово. «Отже, X є важливим, бо…» + що з цього випливає для читача.</div></div><div class=\"final-note\">📌 Скелет на папері (до комп'ютера): 5 рядків = 5 хвилин. Показуй скелет вчителю/науковому керівнику перед написанням — зекономить тижень правок.</div>"],[147,"Складання літературного огляду","<div class=\"rule-note\">📖 <b>Літературний огляд</b> — не реферат (переказ джерел по черзі), а синтез: що відомо з теми, де є суперечності, що залишається невивченим.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: зберіть і відсортуй джерела</b><br>Знайди 10–20 джерел. Розподіли: теоретичні основи, емпіричні дослідження, огляди, суперечливі позиції.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: групуй за ідеями, а не за авторами</b><br>НЕ «Петренко вважає X. Коваленко вважає Y». → «Більшість дослідників погоджуються з X (Петренко, Коваленко), проте...»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: виділи прогалину</b><br>Що досі не досліджено? Де суперечності між авторами? Це місце для твого дослідження: «Однак питання Z залишається відкритим».</div></div><div class=\"final-note\">💡 Структура: загальне → конкретне. Від широкого контексту до вузького питання твого дослідження. Останнє речення огляду → перший крок до твоєї мети.</div>"],[148,"Дизайн навчальних презентацій","<div class=\"rule-note\">🎨 <b>Дизайн слайду</b> — не прикраса, а комунікація. Хороший слайд посилює слова доповідача. Поганий — відволікає від них.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правило одного повідомлення на слайд</b><br>Кожен слайд = одна ідея. Якщо хочеш сказати три речі — зроби три слайди. Більше слайдів — менше тексту на кожному.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Контраст і читабельність</b><br>Темний фон → світлий текст. Світлий фон → темний текст. Мінімальний розмір шрифту: 24pt для тексту, 36pt для заголовків.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зображення замість тексту де можливо</b><br>Мозок обробляє картинку за 13 мс. Текст — набагато повільніше. Велике якісне фото + 5 слів > 10 рядків тексту.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Кольорова схема: максимум 3 кольори</b><br>Основний + акцентний + нейтральний. Уникай «кольорових вибухів». Canva, Coolors.co — готові палітри.</div></div><div class=\"final-note\">📌 Тест «Squint test»: примружся на слайд. Якщо очей не знає, куди дивитись — є проблема з ієрархією. Найважливіше має бути найбільшим або найяскравішим.</div>"],[149,"Перефразування та плагіат","<div class=\"rule-note\">✍️ <b>Перефразування</b> — не синонімічна заміна слів, а повне переосмислення чужої думки своїми словами. Просте перестановлення = прихований плагіат.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три рівні роботи з джерелом</b><br>Цитування: дослівно + лапки + джерело. Перефразування: своїми словами + джерело. Узагальнення: ідея з кількох джерел + джерела.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Алгоритм перефразування</b><br>1. Прочитай → закрий. 2. Запиши своїми словами по пам'яті. 3. Порівняй з оригіналом. 4. Додай посилання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Ознаки плагіату (навіть без копіювання)</b><br>Збережена структура речення, лише слова замінені. Збережений порядок аргументів. Переказ без посилання.</div></div><div class=\"final-note\">📌 Перевірка: Unicheck, Plagiarisma, StrikePlagiarism — сервіси, які використовують у вишах. Шкільні роботи також можна перевірити. Правило: навіть «своїми словами» вимагає посилання на джерело ідеї.</div>"],[150,"Написання анотації до проєкту","<div class=\"rule-note\">📋 <b>Анотація</b> — найчитабельніша частина роботи. Її читають усі, основний текст — одиниці. 150–200 слів, що передають суть проєкту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура анотації (5 елементів)</b><br>1. Актуальність (1–2 реч.). 2. Мета (1 реч.). 3. Методи (1–2 реч.). 4. Основні результати (2–3 реч.). 5. Висновки/значення (1–2 реч.).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пиши анотацію ПІСЛЯ роботи</b><br>Не до, а після завершення. Лише тоді знаєш реальні результати, а не заплановані.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мова анотації</b><br>Пасивний стан: «досліджено», «встановлено», «розроблено». Без «я» і «ми» в академічному стилі. Без скорочень без розшифровки.</div></div><div class=\"final-note\">💡 Тест: дай анотацію людині, яка не читала роботу. Вона має зрозуміти: що досліджувалось, яким методом, що знайшли, що це означає. Якщо ні — переписуй.</div>"],[151,"Формулювання підсумкових висновків","<div class=\"rule-note\">🎯 <b>Висновки</b> — не переказ роботи, а відповіді на завдання, сформульовані у вступі. Кожен висновок = закритий пункт із завдань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура висновків</b><br>Нумерований список: Висновок 1, 2, 3… Кожен відповідає одному завданню зі вступу. Мінімум 3, максимум 7.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мова висновків</b><br>Констатація факту: «Встановлено, що…», «Доведено, що…», «Розроблено…». Конкретні числа і результати, а не «було досліджено багато».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Практичне значення</b><br>Останній висновок: де і як можна застосувати результати. «Отримані результати можуть бути використані для…»</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перспективи подальших досліджень</b><br>Що залишилось за межами роботи і варто дослідити далі? 1–2 речення. Показує наукову зрілість автора.</div></div><div class=\"final-note\">📌 Перевірка висновків: візьми список завдань зі вступу — поруч із кожним має бути відповідний висновок. Завдання без висновку = незавершена робота.</div>"],[152,"Академічне редагування","<div class=\"rule-note\">✏️ <b>Редагування ≠ виправлення помилок</b>. Редагування — це перевірка логіки, структури, аргументації і лише потім — граматики. Ніколи не редагуй відразу після написання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: структурний рівень</b><br>Чи відповідає кожен абзац тезі? Чи є логічний перехід між абзацами? Чи вступ обіцяє те, що висновок виконує?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: абзацний рівень</b><br>Перше речення кожного абзацу — тематичне? Чи всі речення стосуються цієї мікротези? Видали «зайве».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: речення і слова</b><br>Уникай пасивного стану без потреби. Скорочуй: «у зв'язку з тим, що» → «оскільки». Одна ідея — одне речення.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Крок 4: технічний рівень</b><br>Граматика, пунктуація, орфографія. Перевірь цитати і посилання. Єдиний стиль оформлення (шрифт, відступи, заголовки).</div></div><div class=\"final-note\">📌 Правило трьох читань: 1-ше — зміст і логіка, 2-ге — мова і стиль, 3-тє — технічні помилки. Читай вголос — вухо вловлює те, що очей пропускає.</div>"],[153,"Створення інфографіки до захисту","<div class=\"rule-note\">📊 <b>Інфографіка</b> — наочне представлення даних і зв'язків. Одна добра інфографіка замінює сторінку тексту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач тип інфографіки</b><br>Процес → блок-схема. Порівняння → таблиця або бар-чарт. Частини цілого → кругова діаграма. Зміни у часі → лінійний графік. Географія → карта.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Принцип мінімалізму</b><br>Одне повідомлення на одну інфографіку. Прибери всі декоративні елементи, що не несуть інформації. «Якщо можна видалити — видали».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Ієрархія: заголовок → дані → джерело</b><br>Великий чіткий заголовок (що це?). Дані — головний елемент. Внизу — джерело і дата даних.</div></div><div class=\"final-note\">🛠️ Інструменти: Canva (шаблони), Infogram (інтерактивні), Piktochart (наукові), Google Slides (базові діаграми). Колірна схема: 2–3 кольори, контрастний акцент для ключового числа.</div>"],[154,"Формулювання проблемного питання","<div class=\"rule-note\">❓ <b>Проблемне питання</b> — серце дослідження. Має бути конкретним, відкритим (не так/ні) і реально досяжним у межах ресурсів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ознаки хорошого питання</b><br>Починається з «як», «чому», «якою мірою», «які фактори». НЕ «чи є X важливим» (так/ні). НЕ «що таке X» (словникова відповідь).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Масштаб: не надто широко, не надто вузько</b><br>Занадто широко: «Чому люди хворіють?». Занадто вузько: «Яка температура у кімнаті 204 школи №5?». Оптимально: «Як вентиляція класних кімнат впливає на концентрацію учнів?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка питання: 3 критерії</b><br>1. Можу зібрати дані? 2. Відповідь не очевидна заздалегідь? 3. Відповідь матиме практичну цінність?</div></div><div class=\"final-note\">📌 Метод: сформулюй 5 варіантів питання → обери найточніший → перевір за трьома критеріями → узгодь з науковим керівником. Питання можна уточнювати в процесі дослідження.</div>"],[155,"Опис методології дослідження","<div class=\"rule-note\">🔬 <b>Методологія</b> — не список методів, а обґрунтування: ЧОМУ обрано саме ці методи для відповіді на це питання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура опису методології</b><br>Дизайн дослідження (кількісне/якісне/змішане). Вибірка (хто/що, скільки, як обрані). Інструменти збору даних. Аналіз даних.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Кількісні методи</b><br>Експеримент, опитування (шкали Лікерта), вимірювання, статистика. Дають числові дані, статистично значимі висновки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Якісні методи</b><br>Інтерв'ю, спостереження, аналіз документів, фокус-групи. Дають глибоке розуміння явища, але не кількісні узагальнення.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Обмеження методології</b><br>Чесно вкажи: що метод не може виміряти? Яка вибірка не охоплена? Це показує науковий рівень — не слабкість, а чесність.</div></div><div class=\"final-note\">💡 Правило: читач після методології має розуміти, як точно відтворити твоє дослідження. Якщо хтось інший не може повторити — методологія описана недостатньо.</div>"],[156,"Правила академічного цитування","<div class=\"rule-note\">📖 <b>Цитата в тексті</b> — не прикраса, а доказ. Три правила: точність, доречність, помірність. Ніколи не цитуй заради заповнення обсягу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Коли цитувати дослівно</b><br>Визначення і терміни. Статистика. Формулювання, де важливі саме ці слова. Максимум 2–3 цитати на сторінку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вбудовані і блочні цитати</b><br>До 40 слів — вбудована: «...» у тексті + (Автор, рік, с. X). Більше 40 слів — блочна: окремий абзац, відступ, без лапок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вторинне цитування</b><br>Якщо не маєш доступу до оригіналу: «Як зазначав Петренко (цит. за Коваленко, 2020, с. 45)...». Намагайся знайти першоджерело.</div></div><div class=\"final-note\">📌 Пастки: «orphan quote» — цитата без пояснення. «Quote dumping» — суцільний текст із чужих слів. Правило: кожна цитата = твоє пояснення до неї. Думка автора без твого коментаря — не аргумент.</div>"],[157,"Розробка змісту великого проєкту","<div class=\"rule-note\">📋 <b>Зміст проєкту</b> — архітектура перед будівництвом. Не пишуть великий текст без детального плану розділів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура великого проєкту</b><br>Вступ (5–10%). Теоретична частина (20–30%). Практична/дослідницька частина (40–50%). Висновки (5–10%). Список джерел. Додатки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Метод «зверху вниз»</b><br>Спочатку назви розділи → потім підрозділи → потім ключові думки в кожному. Не пиши, поки план не затверджено керівником.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Збалансованість розділів</b><br>Теоретичний розділ ≠ переказ підручника. Він доводить: ти знаєш контекст і позиціонуєш своє дослідження в ньому.</div></div><div class=\"final-note\">📌 Практична порада: після складання змісту — оціни час. Якщо 3 тижні на написання, то: 3 дні теорія, 7 днів практика, 2 дні висновки, 2 дні редагування. Зміст із часовим планом = реальний проєкт.</div>"],[158,"Перевірка контраргументами","<div class=\"rule-note\">⚖️ <b>Контраргумент</b> — не слабкість роботи, а ознака наукової зрілості. Дослідник, що не бачить обмежень свого дослідження, не бачить реальності.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди найсильніший контраргумент</b><br>Поставиться до роботи як опонент. Що може заперечити рецензент? Яке альтернативне пояснення результатів існує?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Три стратегії відповіді</b><br>1. Визнати і обмежити: «Це справедливо для X, але наше дослідження фокусується на Y». 2. Нейтралізувати: надати дані, що спростовують. 3. Включити в обмеження.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Секція «Обмеження дослідження»</b><br>Прямо в тексті назви: вибірка, методи, час, географія. Це підвищує, а не знижує оцінку — показує рефлексію.</div></div><div class=\"final-note\">💡 Тест Поппера: хороша гіпотеза є фальсифікованою — тобто можна уявити дані, що її спростують. Якщо ні — це не наука, а декларація.</div>"],[159,"Побудова діаграм та графіків","<div class=\"rule-note\">📈 <b>Правильний тип графіка</b> — половина успіху. Неправильний тип спотворює дані і вводить в оману навіть без брехні.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Коли який тип</b><br>Порівняння категорій → стовпчиковий. Зміна у часі → лінійний. Частини цілого → кругова (тільки до 5–6 секторів). Зв'язок між змінними → точковий (scatter). Розподіл → гістограма.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Обов'язкові елементи</b><br>Заголовок (що показано). Підписані осі з одиницями. Легенда (якщо кілька рядів). Джерело даних внизу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Частки помилок</b><br>Вісь Y, що не починається з 0 — маніпуляція (стовпчикова). Занадто багато кольорів. 3D-ефекти — спотворюють пропорції. Відсутні підписи осей.</div></div><div class=\"final-note\">🛠️ Google Sheets, Excel, Datawrapper (онлайн, безкоштовно), Flourish — прості інструменти для якісних графіків. Правило: якщо графік вимагає пояснення більше трьох рядків — переробіть його.</div>"],[160,"Структура опису експерименту","<div class=\"rule-note\">🧪 <b>Опис експерименту</b> — протокол відтворюваності. Читач має змогу повторити досвід і отримати ті самі результати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мета і гіпотеза</b><br>Що перевіряємо? Яке припущення? Незалежна змінна (що змінюємо), залежна (що вимірюємо), контрольна (що тримаємо сталим).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Матеріали та обладнання</b><br>Повний список із характеристиками. Не «термометр», а «ртутний термометр, ціна поділки 0.1°C».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Хід роботи — покроково</b><br>Дієслово у наказовому: «Відміряй 50 мл…», «Нагрій до 60°C…». Кожен крок — окремий пункт. Час, температура, кількість — точні числа.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Результати і висновки</b><br>Результати — факти (що спостерігалось). Висновки — інтерпретація (що це означає). Порівняй з гіпотезою: підтверджена? Частково? Спростована?</div></div><div class=\"final-note\">📌 Негативний результат — теж результат. Якщо гіпотеза не підтвердилась — поясни чому. Це наука.</div>"],[161,"Чек-лист вичитки тексту","<div class=\"rule-note\">✅ <b>Вичитка</b> — останній крок перед здачею. Не пропускай цей етап навіть при нестачі часу: 20 хвилин вичитки рятують від прикрих оцінок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зміст і логіка</b><br>☐ Відповідь на всі завдання вступу ☐ Логічний зв'язок між розділами ☐ Немає суперечностей між частинами ☐ Висновки відповідають меті</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мова і стиль</b><br>☐ Академічний стиль (без розмовних слів) ☐ Немає повторів одного слова двічі в одному реченні ☐ Узгодження відмінків і часів ☐ Розділові знаки</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оформлення</b><br>☐ Єдиний шрифт і розмір ☐ Пронумеровані сторінки ☐ Таблиці і рисунки підписані ☐ Список джерел повний ☐ Посилання в тексті збігаються зі списком</div></div><div class=\"final-note\">💡 Порада: вичитуй у зворотному порядку — з кінця до початку. Мозок не «дочитує» знайомий текст, тому помилки на початку пропускаються найчастіше.</div>"]]},{"n":"🎤 Презентації, публічні виступи та робота в команді","e":"","cards":[[162,"Метод Elevator Pitch","<div class=\"rule-note\">🛗 <b>Elevator Pitch</b> — презентація ідеї за 60 секунд. Назва від сценарію: ти входиш в ліфт з директором і маєш один поверх, щоб зацікавити.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура: 4 блоки по 15 секунд</b><br>1. Гачок: «Уявіть, що…» / «Чи знаєте ви, що…» — несподіваний факт або питання. 2. Проблема: яку біль вирішує ідея. 3. Рішення: твоя відповідь у двох реченнях. 4. Заклик: що потрібно від слухача.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Конкретика замість загальних слів</b><br>НЕ «наш продукт кращий». → «Ми скорочуємо час виконання завдання з 2 годин до 15 хвилин».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Репетиція з таймером</b><br>Запиши себе на відео. 60 секунд — жорстко. Виріж зайве. Тренуй до автоматизму.</div></div><div class=\"final-note\">📌 Elevator Pitch використовується: захист проєкту, конкурс ідей, зустріч з рекрутером, стартап-презентація. Навичка, яка потрібна все життя. Вчи зараз — потренуй на захисті.</div>"],[163,"Структура виступу на захисті","<div class=\"rule-note\">🎓 <b>Захист проєкту</b> — не переказ роботи, а переконання комісії. 7–10 хвилин, щоб показати: ти розумієш тему, зробив реальну роботу, отримав цінний результат.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Відкриття (1 хв): зачепи увагу</b><br>Почни з ключового результату або провокаційного питання. НЕ «Добрий день, тема моєї роботи…»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Проблема і мета (1–2 хв)</b><br>Навіщо це потрібно? Яка проблема вирішується? Мета і 2–3 завдання — коротко.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Метод і результати (3–4 хв)</b><br>Що і як робив. Головні знахідки — з цифрами і фактами. Графіки і таблиці — не читай, а коментуй.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Висновки і значення (1–2 хв)</b><br>Що доведено? Де застосувати? Перспективи. Завершення: «Дякую. Готовий(а) відповісти на запитання.»</div></div><div class=\"final-note\">📌 Правило: комісія читала роботу (або прочитає анотацію). Не переказуй — акцентуй на найцікавішому. Захист — це діалог, а не монолог.</div>"],[164,"Подолання страху виступу","<div class=\"rule-note\">😰 <b>Сценічний страх</b> — фізіологічна норма, а не слабкість. 75% людей бояться публічних виступів. Мета — не прибрати страх, а навчитись керувати ним.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Фізіологічна підготовка</b><br>За 5 хвилин до: 5 глибоких вдихів (4 сек вдих — 7 сек затримка — 8 сек видих). Знижує кортизол. Поза «переможця» (широко, впевнено) — 2 хвилини.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Когнітивний рефреймінг</b><br>НЕ «мене оцінюватимуть». → «Я ділюсь тим, що знаю краще за всіх у цій кімнаті». НЕ «я можу облажатись». → «Мені дозволено помилятись і продовжувати».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Підготовка = впевненість</b><br>Знаєш матеріал напам'ять → страх менший. Відрепетируй 3+ разів вголос. Знай перші 30 секунд ідеально — розгін вирішує тон усього виступу.</div></div><div class=\"final-note\">💡 Парадокс: трохи хвилювання покращує виступ — підвищує концентрацію і енергетику. Мета не «нуль страху», а «продуктивний рівень збудження».</div>"],[165,"Розподіл ролей у команді (RACI)","<div class=\"rule-note\">👥 <b>RACI-матриця</b> — інструмент для розподілу відповідальності у команді. Усуває конфлікти «хто за що відповідає» до їхнього виникнення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розшифровка RACI</b><br>R (Responsible) — хто виконує завдання. A (Accountable) — хто несе кінцеву відповідальність (один). C (Consulted) — кого питають. I (Informed) — кого інформують про результат.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як побудувати матрицю</b><br>Рядки = завдання проєкту. Стовпці = члени команди. Клітинки = R/A/C/I або порожньо. Правило: один A на завдання. Якщо R порожньо — завдання нікому не належить.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Переваги для шкільних проєктів</b><br>Уникаєш ситуацію «всі відповідальні = ніхто не відповідальний». Новий учасник одразу бачить свою роль. Оцінювання = чіткий облік внеску кожного.</div></div><div class=\"final-note\">📌 Простіший варіант для команди з 3–5 осіб: Google Таблиця, де рядки — завдання, стовпці — учасники, клітинки — «виконує», «контролює», «допомагає».</div>"],[166,"Відповіді на складні запитання","<div class=\"rule-note\">❓ <b>Відповідь на запитання комісії</b> — окрема навичка. Запитання — не пастка, а можливість показати глибину знань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніка PREP для відповіді</b><br>P (Point) — коротка відповідь одним реченням. R (Reason) — чому так. E (Example) — приклад або дані. P (Point) — повтори висновок.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якщо не знаєш відповіді</b><br>Чесно: «Це виходить за межі мого дослідження, але моє припущення…» Не вигадуй. Комісія поважає чесність більше за гадку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Якщо запитання незрозуміле</b><br>Перепитай: «Уточніть, будь ласка, чи ви маєте на увазі…?» або «Чи правильно я розумію, що ви питаєте про X?» Краще уточнити, ніж відповісти не на те.</div></div><div class=\"final-note\">📌 Підготуй 5 «важких» запитань до свого дослідження заздалегідь. Запитай однокласника пограти роль критика. Репетиція Q&A — найефективніша підготовка до захисту.</div>"],[167,"Невербальна комунікація","<div class=\"rule-note\">🗣️ <b>55–38–7</b> — правило Мерабіана: 55% враження — мова тіла, 38% — голос, лише 7% — слова. <b>⚠️ Увага:</b> дослідження 1967 р. стосується лише передачі почуттів/ставлення, а не будь-якого виступу — сам Мерабіан застерігав від узагальнення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Контакт очей</b><br>Розподіляй погляд: 3–5 секунд на одну людину, потім інша. Не дивись тільки на вчителя. НЕ читай з аркуша — це руйнує контакт.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поза і жести</b><br>Прямий корпус, ноги на ширині плечей, вага рівна. Жести відкриті — долоні вперед. Уникай: схрещені руки, руки в кишенях, торкання обличчя.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пауза — потужний інструмент</b><br>Перед ключовою думкою — пауза 2 секунди. Вона дає час думці дійти. Доповідачі-початківці заповнюють паузи «е-е-е» — треба тренувати мовчання.</div></div><div class=\"final-note\">💡 Запис відео — найкращий спосіб побачити власну невербаліку. Перегляньте відео без звуку — яке враження? Це і є твій невербальний меседж.</div>"],[168,"Управління таймінгом","<div class=\"rule-note\">⏱️ <b>Таймінг</b> — повага до слухачів. Вийти за час — грубість. Завершити занадто рано — непідготовленість. Мета: ±30 секунд від заявленого часу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розбивка часу на блоки</b><br>Наприклад, 7 хвилин: Вступ 1 хв + Теорія 1,5 хв + Практика/результати 3 хв + Висновки 1 хв + «Дякую» 30 сек. Запиши часові мітки на нотатках.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Репетиція з таймером — обов'язково</b><br>Три репетиції: 1-ша — скільки реально йде? 2-га — скорочення/додавання. 3-тя — фінальна швидкість.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Сигнали таймінгу під час виступу</b><br>Дивись на годинник непомітно. Якщо відстаєш — пропускай деталі (не поспішай, а скорочуй). Якщо випереджаєш — уповільнись, додай приклад.</div></div><div class=\"final-note\">📌 Правило: краще закінчити на 20 секунд раніше, ніж на 30 секунд пізніше. Комісія цінує поважне ставлення до регламенту.</div>"],[169,"Сторінтелінг у презентаціях","<div class=\"rule-note\">📖 <b>Сторінтелінг</b> — будь-яка ідея засвоюється краще, якщо її подати як історію. Мозок запам'ятовує наративи значно краще, ніж сухі списки фактів — дослідження фіксують кратне покращення запам'ятовування при поданні у формі історії.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура: Герой → Проблема → Рішення</b><br>Герой = твій «споживач» або тестована група. Проблема = що заважає. Рішення = твоє дослідження/продукт/ідея.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Конкретний персонаж замість абстракції</b><br>НЕ «учні школи страждають від стресу». → «Уявіть Оксану, 10-класницю, яка о 23:00 ще не почала готуватись до контрольної».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Емоційний гачок на початку</b><br>Факт, що дивує. Коротка історія. Несподіване питання. Перші 30 секунд вирішують, чи слухатиме аудиторія далі.</div></div><div class=\"final-note\">💡 Структура TED Talk: Конкретна ідея → 3 аргументи з прикладами → Заклик до дії. Це і є сторінтелінг у публічному виступі. Переглянь 1–2 TED Talks — помітиш шаблон.</div>"],[170,"Вирішення конфліктів у команді","<div class=\"rule-note\">🤝 <b>Конфлікт у команді</b> — нормально. Це сигнал: різні бачення, різні пріоритети. Мета — перевести деструктивний конфлікт у конструктивний діалог.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: визнач тип конфлікту</b><br>Конфлікт завдання (як робити?) — корисний, веде до кращих рішень. Конфлікт відносин (проблема з людиною) — руйнівний, треба гасити.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Техніка «Я-повідомлення»</b><br>НЕ «Ти завжди запізнюєшся!» → «Я відчуваю стрес, коли матеріали приходять пізно, бо я не встигаю підготуватись». Факт + мій стан + вплив на мене.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Метод 5 кроків</b><br>1. Вислухай без перебивання. 2. Перефразуй (переконайся, що зрозумів). 3. Знайди спільне. 4. Запропонуй компроміс. 5. Зафіксуй домовленість.</div></div><div class=\"final-note\">📌 У командному проєкті конфлікти неминучі. Команди, що навчились конструктивно сперечатись, показують кращі результати, ніж ті, де «всі згодні».</div>"],[171,"Використання описових карток","<div class=\"rule-note\">🃏 <b>Описові картки</b> (note cards) — фізичний або цифровий інструмент організації ідей. Кожна картка = одна думка. Переставляй, групуй, відкидай.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Для підготовки виступу</b><br>На кожній картці: 1 ключова думка + 1 підтвердження/приклад. 7–10 карток на 7-хвилинний виступ. Порядок можна змінювати до останнього моменту.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Метод Корнелла для нотаток</b><br>Аркуш ділиться: ліва 1/3 — ключові слова і питання; права 2/3 — основні нотатки; низ — підсумок. Після лекції — закрий праву частину, відповідай за ключовими словами.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Цифровий аналог</b><br>Trello, Notion, Miro — дошки із картками. Перевага: пошук, теги, посилання. Для презентацій — Google Slides у режимі сортувальника.</div></div><div class=\"final-note\">💡 Метод феришмана (Farnam Street): після читання без перегляду — запиши головні ідеї своїми словами на картках. Те, що не можеш пояснити — не зрозумів.</div>"],[172,"Робота з презентаційною технікою","<div class=\"rule-note\">💻 <b>Технічні питання на захисті</b> — найчастіша причина стресу. Готуйся до відмови техніки ще до початку — тоді не будеш паніковане.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перевірка за 30 хвилин до виступу</b><br>☐ Файл відкривається на чужому комп'ютері ☐ Шрифти не замінились ☐ Відео/звук працює ☐ Анімації не зависають ☐ Слайдів потрібна кількість</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формат: PDF як резервний</b><br>Завжди май PDF-версію. PDF — незмінний, відкривається на будь-якому пристрої, без проблем зі шрифтами. USB-флешка + пошта собі.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Якщо техніка відмовила</b><br>Спокійно повідом комісії: «Технічна проблема, прошу хвилину». Відкрий PDF з телефону або роздруковані тези. Або проводь виступ без слайдів — якщо знаєш матеріал, це можливо.</div></div><div class=\"final-note\">📌 Правило: нікому не цікаві твої технічні проблеми. Комісія оцінює, як ти з ними справляєшся. Спокійна реакція на збій = плюс до оцінки.</div>"],[173,"Фасилітація брейнстормінгу","<div class=\"rule-note\">🧠 <b>Брейнсторм</b> — не хаотичне кидання ідей, а структурований процес. Брейнсторм корисний для розвитку і комбінування ідей. Водночас, дослідження показують: попередня індивідуальна генерація ідей дає більше різноманітних варіантів — тому ефективніший формат: спершу кожен думає сам, потім ділиться з групою.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правила класичного брейнсторму</b><br>1. Кількість важливіша за якість (зібрати 50+ ідей). 2. Заборона критики під час генерації. 3. Вітаються дикі ідеї. 4. Розвивай чужі ідеї.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Роль фасилітатора</b><br>Не бере участь в генерації — веде процес. Фіксує всі ідеї (дошка/фліпчарт). Слідкує за часом. Стимулює мовчазних: «А що думаєш ти?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оцінка ідей (після генерації)</b><br>Крапки (dot voting): кожен ставить 3–5 крапок на найкращих ідеях. Матриця вплив × зусилля: швидкі перемоги (висока ефективність + мало зусиль) — першочергово.</div></div><div class=\"final-note\">💡 Брейнсторм для двох: «Так, і…» — додавай до ідеї партнера, не заперечуй. Метод 6–3–5: 6 осіб × 3 ідеї × 5 раундів = 90 ідей за 30 хвилин.</div>"],[174,"Презентація інноваційних ідей","<div class=\"rule-note\">💡 <b>Pitch інноваційної ідеї</b> — поєднання логіки (дані, докази) і емоції (навіщо це потрібно). Лише логіка — нудно. Лише емоція — не переконливо.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формат Problem-Solution-Impact</b><br>Проблема: масштаб + конкретний приклад. Рішення: як саме вирішує проблему + чим відрізняється від наявних. Вплив: хто і як виграє, кількісно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Доказова база</b><br>Прототип або MVP. Тестування з реальними користувачами. Дані або дослідження, що підтверджують проблему. Навіть на шкільному рівні — опитування 20 осіб.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Антипатерни</b><br>НЕ «наш продукт кращий за всі аналоги». → «На відміну від X, ми вирішуємо саме Y тому що Z». НЕ «ринок величезний» без джерела.</div></div><div class=\"final-note\">📌 Шаблон однієї сторінки: Проблема (3 реч.) + Рішення (3 реч.) + Аудиторія + Ключова відмінність + Наступний крок. Якщо ідею можна пояснити на аркуші — вона достатньо ясна.</div>"],[175,"Конструктивне сприйняття критики","<div class=\"rule-note\">🛡️ <b>Критика роботи ≠ критика тебе</b>. Відокремити «мою роботу» від «мене» — ключова навичка для розвитку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Реакція в момент</b><br>Перше правило: не відповідай одразу. «Дякую, цікаве зауваження» — час обдумати. НЕ виправдовуйся. НЕ нападай у відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Аналіз критики</b><br>Питання собі: Чи критика конкретна? Чи є в ній зерно правди? Що саме я можу змінити? Якщо критика розмита — уточни: «Що конкретно варто покращити?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відповідь на захисті</b><br>Якщо критика справедлива: «Дякую, ви маєте рацію. Це обмеження нашого дослідження». Якщо незгоден: «Я розумію вашу точку зору. Дозвольте пояснити, чому ми обрали інший підхід...»</div></div><div class=\"final-note\">💡 Психологічна установка: критика — безкоштовна порада від досвідченішої людини. Скористатися нею чи ні — твій вибір. Але обдумати варто завжди.</div>"],[176,"Голосова динаміка","<div class=\"rule-note\">🎙️ <b>Голос</b> — головний інструмент доповідача. Монотонний голос = «мені самому нецікаво». Динамічний голос = «слухай уважно, тут важливе».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Темп: варіюй навмисно</b><br>Нормальний темп — 130–150 слів/хв. Уповільнення на ключовій думці — сигнал важливості. Прискорення на тлі → ефект захопленості.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гучність: грай на контрастах</b><br>Гучніше = впевненість, акцент. Тихіше = інтимність, таємниця — аудиторія схиляється, щоб почути. Крайності — рідко, лише для ефекту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пауза замість «ем» і «ну»</b><br>Слова-паразити з'являються, коли мозок думає швидше за мову. Тренування: «зловлюй» паразит → зупинись → продовжуй після паузи. 2–3 тижні практики.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Артикуляція і дикція</b><br>Скоромовки перед виступом (5 хвилин). Відкривай рот ширше, ніж здається природним. Відеозапис + прослуховування без зображення.</div></div><div class=\"final-note\">📌 Вправа: прочитай один абзац тексту 4 рази: 1) монотонно, 2) дуже голосно, 3) дуже тихо, 4) природньо з паузами. Четвертий варіант — твій робочий голос.</div>"],[177,"Відеорепетиція виступу","<div class=\"rule-note\">📹 <b>Відеорепетиція</b> — найефективніший спосіб підготовки до публічного виступу. Те, що ти бачиш у записі, аудиторія бачить завжди.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як записувати</b><br>Встав у повний зріст або як буде на захисті. Запис без зупинок — повний виступ від початку до кінця. Кілька дублів у різні дні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що аналізувати</b><br>Темп мовлення. Слова-паразити. Жести і поза. Контакт з камерою (= контакт з аудиторією). Чи вкладаєшся в час?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Порівняй дублі</b><br>Перший запис — найчесніший. Останній — прогрес. Різниця між ними = навчання. Збережи обидва для мотивації.</div></div><div class=\"final-note\">📌 Дискомфорт від перегляду себе — нормальний. Всі через це проходять. Перші 3 рази — важко, потім звикаєш бачити себе об'єктивно. Це і є мета.</div>"],[178,"Спільні цифрові простори","<div class=\"rule-note\">☁️ <b>Цифровий простір команди</b> — де зберігаються файли, комунікація і завдання. Хаос у файлах = хаос у проєкті.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зберігання файлів</b><br>Google Drive або OneDrive: спільна папка з чіткою структурою. Правило іменування: «2024_назва_версія» НЕ «фінал_фінал2_точно_фінал».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Комунікація</b><br>Viber/Telegram-група для оперативного зв'язку. Важливі рішення фіксуй текстом — «відео не зберігається», зате скриншот рішення — так.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відстеження завдань</b><br>Trello (безкоштовно): дошка з колонками «Треба зробити / В процесі / Готово». Альтернатива: спільна Google Таблиця з дедлайнами.</div></div><div class=\"final-note\">💡 Правило: будь-яке завдання без виконавця і дедлайну — не завдання, а побажання. Цифровий простір тільки тоді допомагає, коли команда дотримується правил його ведення.</div>"],[179,"Уніфікація командного стилю","<div class=\"rule-note\">🎨 <b>Єдиний стиль команди</b> — коли всі слайди, документи і матеріали виглядають як одне ціле, а не колаж з різних проєктів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Style Guide команди (1 сторінка)</b><br>Шрифт (1–2 типи). Колірна палітра (3–4 кольори + HEX-коди). Розмір заголовків і тексту. Відступи. Шаблон слайду.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Шаблон документу</b><br>Один Google Doc або Word-файл з правильним форматуванням = шаблон для всіх. Всі нові файли — копія шаблону.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка перед здачею</b><br>Один учасник команди переглядає ВСІ матеріали на відповідність стилю. 30 хвилин роботи — єдиний вигляд.</div></div><div class=\"final-note\">📌 Навіщо це важливо: комісія підсвідомо вище оцінює роботи з єдиним стилем — сприймає як ознаку організованості та зрілості команди.</div>"],[180,"Експрес-пітч для ментора","<div class=\"rule-note\">⚡ <b>Пітч для ментора/викладача</b> — коротке оновлення за 2–3 хвилини: де ми зараз, що заблоковано, що потрібно від вас.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура: Прогрес → Блокери → Запит</b><br>Прогрес: «Зробили X і Y, зараз на етапі Z». Блокери: «Застрягли на…, тому що…». Запит: «Нам потрібна ваша допомога з…»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підготовка за 5 хвилин</b><br>Запиши 3 речення до зустрічі: 1) що зроблено, 2) що заважає, 3) що просиш. Без підготовки зустріч перетворюється на скаргу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Частота комунікації з ментором</b><br>Раз на тиждень — мінімум для активного проєкту. Не чекай, поки проблема стане кризою. «Маленький сигнал вчасно» краще, ніж «SOS у останній момент».</div></div><div class=\"final-note\">💡 Правило: приходь до ментора з проблемою + варіантом рішення, не лише з проблемою. «Ми думаємо зробити X, що скажете?» — набагато кращий старт розмови.</div>"],[181,"Складання поміток спікера","<div class=\"rule-note\">📝 <b>Нотатки спікера</b> — не текст для читання, а навігатор. Допомагають не загубитись, не підказують кожне слово.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формат нотаток</b><br>Ключові слова, а не речення. 5–7 слів на пункт. Шрифт 18+ пт — читається з відстані. Нумерація відповідає слайдам.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що писати</b><br>Перші слова речення (розгін). Числа і статистику (складно пам'ятати точно). Перехідні фрази між блоками. Нагадування: «ПАУЗА», «ПОВІЛЬНІШЕ», «ПОДИВИСЬ НА АУДИТОРІЮ».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як тримати</b><br>Один аркуш або картки — не зошит. Тримай збоку або на столі (не перед обличчям). Не читай і не дивись постійно — лише швидкий погляд для підказки.</div></div><div class=\"final-note\">📌 Тест: закрий нотатки і розкажи виступ. Якщо втрачаєшся без них — ще треба репетирувати. Нотатки — страховка, не сценарій.</div>"]]},{"n":"🎯 Стратегія іспитів, тайм-менеджмент та саморегуляція","e":"","cards":[[182,"Тріумвірат планування","<div class=\"rule-note\">📅 <b>Три горизонти планування</b> — бачити одночасно далеко, середньо і близько. Лише «на сьогодні» = реактивний режим. Лише «на рік» = мрії без дій.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Довгострокове (місяць/семестр)</b><br>Дедлайни всіх проєктів і контрольних. Іспити. Важливі події. Раз на тиждень — перегляд. Інструмент: Google Calendar або паперовий розворот.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Середньострокове (тиждень)</b><br>Щонеділі: що треба зробити цього тижня? Розбити на дні. Реалістично — 3–5 важливих справ, не 20.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Короткострокове (день)</b><br>Вранці або ввечері попереднього дня: 3 пріоритетні завдання. MIT (Most Important Task) — виконати першим, до пар чи зразу після.</div></div><div class=\"final-note\">📌 Правило: якщо завдання немає в календарі — воно не існує. «Я пам'ятаю» = «я забуду в найвідповідальніший момент».</div>"],[183,"Стратегія складання тестів (НМТ/ЗНО)","<div class=\"rule-note\">📝 <b>Стратегія на іспиті</b> — не лише знання, а й тактика роботи з тестом. Правильна стратегія дає +5–10% до результату без додаткових знань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три проходи по тесту</b><br>1-й: швидкі відповіді (знаю точно — відповідаю, решта — пропускаю). 2-й: складні питання (думаю, відповідаю). 3-й: решта (метод відсікання або вгадування).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Таймінг</b><br>Підрахуй: час / кількість питань = середній час на питання. 90 хв / 60 питань = 1.5 хв/питання. Якщо питання забирає > 3 хв — помітити, пропустити, повернутись.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка відповідей</b><br>Якщо є час — перевіряй лише відмічені сумнівні питання, а не всі підряд. Змінюй відповідь лише якщо є чітке обґрунтування, не «мені так здається».</div></div><div class=\"final-note\">💡 Психологія: не застрягай на одному питанні. Пропустив — рухайся вперед. Решта питань вже чекають, і вони можуть бути легшими.</div>"],[184,"Матриця Ейзенхауера","<div class=\"rule-note\">⚡ <b>Матриця Ейзенхауера</b> — найпростіший інструмент пріоритизації. Розділяє «терміново» і «важливо» — це не одне й те саме.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>4 квадранти</b><br>Q1: Терміново + Важливо → роби зараз (кризи, дедлайни). Q2: НЕ терміново + Важливо → плануй (навчання, підготовка). Q3: Терміново + НЕ важливо → делегуй або скорочуй. Q4: НЕ терміново + НЕ важливо → виключи (соцмережі без мети).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пастка Q1</b><br>Більшість людей живуть у Q1 — постійні «пожежі». Причина: ігнорування Q2. Час у Q2 (підготовка, планування) скорочує Q1.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як застосувати щодня</b><br>Вранці: запиши 5–7 справ. Постав у матрицю. Q1 — першочергово. Q2 — заплануй конкретний час. Q3 і Q4 — мінімізуй.</div></div><div class=\"final-note\">📌 Правило: успішні студенти проводять більше часу в Q2 (підготовка, повторення, здоров'я), ніж у Q1 (аврали). Планування = профілактика криз.</div>"],[185,"Експрес-аудит знань","<div class=\"rule-note\">🔍 <b>Аудит знань</b> — перевірка що знаєш, а що лише «думаєш що знаєш». Знання без перевірки — ілюзія знань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніка: закрита книга → відтворення</b><br>Закрий підручник. Запиши все, що пам'ятаєш з теми. Порівняй з джерелом. Прогалини = точки для повторення.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Флеш-картки для самоперевірки</b><br>Питання на одній стороні, відповідь на іншій. Переберай колоду: «знаю» відклади, «не знаю» — повтори. Алгоритм Лейтнера.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Метод «навчи іншого»</b><br>Поясни тему другу або уявній аудиторії. Де спотикаєшся — там прогалина. «Якщо не можеш пояснити просто — ти не розумієш» (Фейнман).</div></div><div class=\"final-note\">💡 Науковий факт: активне відтворення (testing effect) ефективніше за перечитування у 2–3 рази. 10 хвилин самоперевірки > 30 хвилин пасивного читання.</div>"],[186,"Техніка відновлення після навантажень","<div class=\"rule-note\">🔋 <b>Відновлення</b> — частина продуктивності, а не її ворог. Мозок, як м'яз: без відпочинку — деградує, а не тренується.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мікровідпочинок (5–15 хв)</b><br>Після кожних 90 хв роботи. Прогулянка. Розтяжка. Склянка води. НЕ соцмережі — це не відпочинок, це інший вид навантаження.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якісний сон — пріоритет</b><br>7–9 годин для підлітків і студентів. Навіть помірне недосипання (на 1–2 год) помітно знижує когнітивні функції: увагу, робочу пам'ять і здатність приймати рішення — це підтверджено численними дослідженнями. Перед сном: без екранів за 30 хв.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відновлення після сесії</b><br>День без навчання після інтенсивного тижня — не лінощі, а необхідність. Планові перерви запобігають вигоранню.</div></div><div class=\"final-note\">📌 Парадокс продуктивності: 6 год роботи з відпочинком ефективніші за 10 год без зупинки. Відпочинок — не винагорода за роботу, а умова її якості.</div>"],[187,"Стратегія ліквідації заборгованостей","<div class=\"rule-note\">📚 <b>Навчальні борги</b> — накопичуються швидко, ліквідуються важко. Але є система, яка дозволяє наздогнати без паніки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: Інвентаризація боргів</b><br>Список: предмет → що конкретно заборговано → дедлайн ліквідації. Не «все по хімії», а «лабораторна №3, тема X, здати до П'ятниці».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: Пріоритизація</b><br>Спочатку: борги, що блокують допуск до іспиту. Потім: найбільша вага в оцінці. Останні: «для заліку але не критично».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: Денний план ліквідації</b><br>По 1–2 борги на день, крім основного навчання. Не намагайся закрити все за один день — гарантований провал.</div></div><div class=\"final-note\">💡 Психологічний лайфхак: почни з найлегшого боргу. Перше «закрите» завдання дає мотивацію і імпульс для решти. Список боргів, що скорочується — найкраща мотивація.</div>"],[188,"Утримання фокусу на парах","<div class=\"rule-note\">🎯 <b>Утримання уваги</b> на лекції — активна навичка, а не пасивний стан. Середній час концентрації на одній темі — 10–20 хвилин.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніка активного слухання</b><br>Нотатки своїми словами (не диктування). Знак «?» навпроти незрозумілого. Знак «!» навпроти важливого. Питання до себе: «Навіщо це знати?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якщо увага розсіялась</b><br>Нормально. Помітив — поверни. Тактика: знайди в нотатках останнє, що зафіксував → спитай сусіда що пропустив → не паст у безвихідь.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило передніх рядів</b><br>Студенти в перших 2–3 рядах отримують вищі оцінки статистично. Пояснення: менше відволікань, більше контакту з викладачем, ефект «на мене дивляться».</div></div><div class=\"final-note\">📌 До пари: переглянь попередні нотатки (5 хв). На парі: закрий телефон фізично. Після пари: перечитай нотатки, доповни пам'яттю (перші 20 хвилин після — найефективніші).</div>"],[189,"Розклад інтервальних повторень","<div class=\"rule-note\">🔄 <b>Інтервальне повторення</b> — науково доведений спосіб запам'ятовування. Повторення у момент «майже забув» закріплює матеріал краще, ніж повторення відразу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крива забування Еббінгауза</b><br>Без повторення матеріал забувається швидко: більша частина губиться вже за перші дні, а за місяць без закріплення залишається лише незначний відсоток. Еббінгауз показав цю залежність ще у XIX ст. — сучасні дослідження підтверджують загальний принцип для змістового матеріалу. З повторенням — крива піднімається.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розклад повторень</b><br>Після вивчення: повторення через 1 день → 3 дні → 7 днів → 21 день → 60 днів. Кожне повторення подовжує час до наступного.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Інструменти</b><br>Anki (безкоштовно) — алгоритм сам розраховує коли повторювати. Quizlet — для флеш-карток. Ручні картки з датою «наступного повторення» на звороті.</div></div><div class=\"final-note\">📌 Для підготовки до НМТ: починай за 3–4 місяці. Щодня 20–30 хвилин інтервального повторення ефективніші за 3 доби безперервного читання перед іспитом.</div>"],[190,"Подолання синдрому самозванця","<div class=\"rule-note\">🎭 <b>Синдром самозванця</b> — відчуття «я недостатньо хороший, мене викриють». За різними дослідженнями, більшість успішних людей хоча б раз переживають це відчуття. Знати про нього — перший крок до подолання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розпізнай патерн</b><br>Ознаки: применшуєш свої досягнення («просто пощастило»). Боїшся, що «зловлять» на незнанні. Порівнюєш свої слабкості з чужими сильними сторонами.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Когнітивна переоцінка</b><br>Веди «Список доказів»: записуй кожне досягнення, позитивний відгук, подолану труднощу. Під час кризи самозванця — відкривай і читай.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нормалізація незнання</b><br>«Я не знаю» — не ганьба, а чесність. «Я дізнаюсь» — це компетентність. Питання на парі = сміливість, не слабкість. Ніхто не знає всього.</div></div><div class=\"final-note\">💡 Факт: Альберт Ейнштейн, Майя Анджелу, Мішель Обама відкрито говорили про синдром самозванця. Він не залежить від реального рівня компетентності — це когнітивне викривлення.</div>"],[191,"Цифровий детокс під час навчання","<div class=\"rule-note\">📵 <b>Цифровий детокс</b> — не відмова від технологій, а свідоме управління ними. Телефон поруч знижує концентрацію навіть якщо ти його не чіпаєш.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Техніки блокування відволікань</b><br>Телефон — в інший кімнаті або в ящику (не лише на безшумному). Forest App — рости дерево, поки не чіпаєш телефон. Cold Turkey / Freedom — блокує сайти на комп'ютері.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пакетна обробка соцмереж</b><br>Перевіряй соцмережі у визначені часові вікна: наприклад, 13:00 і 20:00. Між ними — режим літака. Нотифікації вимкнені завжди.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило 20 секунд</b><br>Відклади телефон туди, звідки дістати потрібно 20+ секунд зусиль. Дрібний бар'єр знищує 80% імпульсивних перевірок.</div></div><div class=\"final-note\">📌 Дослідження: студенти, що навчаються без смартфона поруч, показують результати на 20% вищі при тих самих знаннях. Відстань від телефону = приріст продуктивності.</div>"],[192,"Персональна система заохочень","<div class=\"rule-note\">🏅 <b>Система заохочень</b> — самомотивація через дофамін. Мозок повторює поведінку, що приносить винагороду. Запрограмуй свій мозок на навчання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Негайні малі заохочення</b><br>Після виконання MIT (головного завдання дня): 15 хв улюбленого серіалу, кава, прогулянка. Невідкладно — мозок пов'язує зусилля з приємним.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Тижневі нагороди</b><br>Виконав план тижня → щось приємне на вихідних. Не «якщо все зробив ідеально», а «якщо зробив заплановане».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Система трекінгу</b><br>Habit tracker: кожен день навчання — відмітка. Серія позначок (streak) сама по собі мотивує не переривати. GitHub-подібна таблиця прогресу.</div></div><div class=\"final-note\">💡 Правило Голдіфлокса: завдання має бути не надто легким (нудьга) і не надто важким (тривога) — а на межі можливостей. Це стан потоку, де навчання відбувається найкраще.</div>"],[193,"Стратегія здорового сну в сесію","<div class=\"rule-note\">😴 <b>Сон під час сесії</b> — не розкіш, а стратегія. Під час сну мозок консолідує пам'ять. Нічне читання без сну знищує те, що вивчив вдень.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Мінімальний стандарт</b><br>6 годин — абсолютний мінімум для функціонування. 7–8 — оптимально. Нижче 5 год → когнітивні функції падають як при алкогольному сп'янінні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гігієна сну в сесію</b><br>Вставай в один час навіть у вихідні (стабілізує цикл). Останній прийом їжі — за 2 год до сну. Уникай кофеїну після 15:00.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>«Нічне зубріння» — міф</b><br>Матеріал, вивчений вночі без сну, засвоюється на 40% гірше. Краще: вчи до 23:00 → сон → 30 хв повторення вранці перед іспитом.</div></div><div class=\"final-note\">📌 Лайфхак: 20-хвилинний денний сон (power nap) відновлює концентрацію на 2–3 год. Не більше 30 хвилин — інакше входиш у глибокий сон і прокидаєшся розбитим.</div>"],[194,"Трекінг навчальних звичок","<div class=\"rule-note\">📊 <b>Трекінг звичок</b> — зробити прогрес видимим. Те, що вимірюєш — покращуєш. Те, що не відстежуєш — зникає.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що трекувати</b><br>Щоденне навчання (год/хв). Виконання плану дня (так/ні). Повторення за Anki. Прочитані сторінки. Вирішені задачі. Вибирай 2–3 метрики, не 10.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формати трекера</b><br>Папір: таблиця в зошиті, щоденник. Додатки: Habitica (гейміфікація), Streaks, Notion. Google Sheets: власна таблиця.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Аналіз раз на тиждень</b><br>П'ятниця або неділя: переглянь тиждень. Що виконав? Де провали? Що заважало? Скоригуй план на наступний тиждень.</div></div><div class=\"final-note\">💡 Психологія: бачення власного прогресу — один з найсильніших мотиваторів. Навіть просте «відмітив галочку» дає задоволення і бажання продовжувати.</div>"],[195,"Аналіз навчальних невдач","<div class=\"rule-note\">🔎 <b>Аналіз невдачі</b> — найцінніший освітній інструмент. Провалений тест без аналізу = втрачена можливість. З аналізом = урок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>5 питань після невдачі</b><br>1. Що конкретно не знав? 2. Чому не знав (не вчив / не зрозумів / переплутав)? 3. Які питання вирішив правильно? 4. Що зроблю по-іншому? 5. Коли повторю цей матеріал?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розбір помилок в тесті</b><br>Кожну помилку — поясни собі. «Я обрав А, тому що думав X. Правильно Б, тому що Y». Запиши. Це — персональний довідник слабких місць.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відокремлення результату від зусиль</b><br>Погана оцінка ≠ ти дурний. Погана оцінка = конкретна прогалина + конкретний спосіб виправити. Результат — зворотній зв'язок, не вирок.</div></div><div class=\"final-note\">📌 Метод «post-mortem»: після будь-якого важливого іспиту або проєкту — 15 хвилин розбору. Що вдалось? Що ні? Що зміню? Занеси в нотатки.</div>"],[196,"Адаптація до нового навчального закладу","<div class=\"rule-note\">🏫 <b>Адаптація</b> — перший місяць у новому закладі визначає наступний рік. Активна адаптація vs. чекання «само налагодиться».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перший тиждень: орієнтація</b><br>Вивчи розклад, аудиторії, де їдальня/бібліотека/туалет. Запам'ятай 2–3 імена однокурсників. Знайди, де шукати інформацію (сайт, чат групи, дошка оголошень).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перший місяць: система</b><br>Познайомся з викладачами особисто: задай питання після пари. Знайди «старшого» — студента старшого курсу, що поясняє «як тут все влаштовано».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Соціальна адаптація</b><br>Приєднайся до одного гуртка або команди — за інтересами, не заради «корисних зв'язків». Спільна діяльність = природні знайомства.</div></div><div class=\"final-note\">💡 Норма: перші 2–4 тижні — дискомфорт, невизначеність, стрес. Це фізіологічна реакція на нове середовище. Якщо через 2 місяці не стало краще — шукай підтримку.</div>"],[197,"Контроль стресу на іспитах","<div class=\"rule-note\">🧘 <b>Стрес на іспиті</b> — фізіологія, яку можна регулювати. Мета: перевести деструктивний стрес (паніка) у продуктивний (збудження і фокус).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>За день до іспиту</b><br>Не вчи нового матеріалу (підвищує тривогу). Лише легке повторення + ранній сон. Підготуй все: документи, одяг, дорогу. Вечір = відпочинок.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ранок іспиту</b><br>Сніданок (глюкоза = паливо для мозку). Повторення ключових тез 20–30 хв — активує пам'ять. Вийди заздалегідь — запізнення = паніка.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Під час іспиту</b><br>Перші 2 хвилини: 5 глибоких дихань. Прочитай всі питання перед тим, як відповідати. Почни з легкого — активує впевненість. «Я готувався до цього» — твоя мантра.</div></div><div class=\"final-note\">📌 Переосмислення: дослідники з Гарварду показали, що сказати собі «я збуджений» (замість «я нервую») покращує результати. Збудження і тривога — однакова фізіологія, різна інтерпретація.</div>"],[198,"Щотижнева рефлексія продуктивності","<div class=\"rule-note\">🔄 <b>Weekly Review</b> (тижневий огляд) — 30 хвилин, які роблять наступний тиждень кращим за попередній. Система без огляду — корабель без штурмана.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: Що зроблено (10 хв)</b><br>Переглянь список завдань і календар. Відміть виконане. Перенеси невиконане або видали. Що приніс цей тиждень?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: Аналіз (10 хв)</b><br>Що заважало? Де втрачав час? Що вдалось краще за звичайно? Одна навичка для покращення наступного тижня.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: Планування (10 хв)</b><br>Дедлайни наступного тижня. 3–5 головних результатів, яких хочу досягти. MIT на понеділок.</div></div><div class=\"final-note\">💡 GTD (Getting Things Done) Девіда Аллена: мозок — не місце для зберігання завдань. Виніс все в систему → мозок вільний для творчості і навчання, а не для тривожного «не забути».</div>"],[199,"Ергономіка навчального місця","<div class=\"rule-note\">💺 <b>Ергономіка</b> — наука про зручність. Правильно організоване місце знижує втомлюваність і підвищує концентрацію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Фізичне середовище</b><br>Монітор — на рівні очей або трохи нижче. Спина — пряма, підтримана. Ноги — на підлозі або підставці. Відстань до екрану — 50–70 см.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Освітлення</b><br>Природне світло — зліва (для правшів). Штучне — без тіней на робочій поверхні. Теплий жовтий ввечері (менше навантаження на очі). Яскравість екрану = яскравість кімнати.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Температура і повітря</b><br>18–22°C — оптимально для концентрації. Провітрювання кожні 60–90 хв — CO₂ накопичується і знижує увагу. Вода на столі — зневоднення знижує когнітивні функції.</div></div><div class=\"final-note\">📌 Правило 20-20-20 для очей: кожні 20 хвилин — 20 секунд дивись на об'єкт за 20 футів (6 метрів). Знімає напругу очних м'язів.</div>"],[200,"Поведінка при незнайомому питанні","<div class=\"rule-note\">❓ <b>Незнайоме питання</b> на іспиті або захисті — не катастрофа. Як ти реагуєш на незнане — це теж компетентність.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Не мовчи — думай вголос</b><br>«Це цікаве питання. Якщо я правильно розумію, воно стосується X. Виходячи з того, що я знаю про Y, можу припустити, що…» Процес мислення — вже відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Метод аналогії</b><br>Знайди схоже питання, відповідь на яке знаєш. «Я не знаю конкретно про Z, але принцип схожий на W, де…» Перенесення знань — ознака розуміння.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Чесність з гідністю</b><br>«Я не вивчав це питання детально, але моя гіпотеза…» краще ніж вигадана впевнена відповідь. Педагоги чудово відрізняють незнання від брехні.</div></div><div class=\"final-note\">📌 Золоте правило: ніколи не кажи «не знаю» і мовчиш. Завжди: «не знаю точно, але розмірковую так…» Думати вголос — показник інтелекту, а не слабкості.</div>"],[201,"Фіксування досягнень","<div class=\"rule-note\">🏆 <b>Щоденник досягнень</b> — противага синдрому самозванця і інструмент мотивації. Мозок природньо фіксує невдачі краще, ніж успіхи (негативне упередження).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формат записів</b><br>Щодня: 1–3 речення. «Сьогодні я…» — конкретно, не «добре навчався». Приклад: «Розв'язав задачу з фізики, що не виходила тиждень. Пояснив Михайлу теорему».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Категорії досягнень</b><br>Академічні (оцінки, завдання). Соціальні (допоміг, познайомився). Особистісні (подолав страх, не відклав). Навички (навчився чомусь новому).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Використання щоденника</b><br>Перед іспитом або захистом — перечитай. Під час кризи самозванця — відкрий. Раз на семестр — огляд росту за місяці.</div></div><div class=\"final-note\">📌 Великий результат складається з малих кроків. Щоденник досягнень — доказ, що кроки були. Навчання — це марафон: бачити пройдений шлях важливо не менше, ніж дистанцію, що залишилась.</div>"]]}]};
if(window.__catLoaded)window.__catLoaded(2,CAT_2);